        anna_v_name: 'Анна В.',
        time_msg_lateNight_0: 'Я не могу спать... снова эти звуки за окном.',
        time_msg_lateNight_1: 'Прости, что так поздно. Мне просто нужно с кем-то поговорить.',
        time_msg_lateNight_2: 'Ты тоже не спишь? Мне кажется, я схожу с ума.',
        time_msg_lateNight_3: 'В три часа ночи всегда самое страшное время...',
        time_msg_lateNight_4: 'Слышишь? Этот скрип. Он снова здесь.',
        time_msg_lateNight_5: 'Я боюсь закрыть глаза. Вдруг я не проснусь?',
        time_msg_lateNight_6: 'Ночью все звуки кажутся громче. Даже собственное сердце.',
        time_msg_lateNight_7: 'Посмотри в окно. Видишь тот фонарь? Он мигает уже час.',
        time_msg_deepNight_0: 'Три часа ночи. Говорят, это время демонов.',
        time_msg_deepNight_1: 'Я слышала шаги на лестнице. Сейчас. Только что.',
        time_msg_deepNight_2: 'Не спишь? Мне страшно. Очень страшно.',
        time_msg_deepNight_3: 'Кто-то пробовал открыть дверь. Я слышала, как скрипнула ручка.',
        time_msg_deepNight_4: 'Тишина... слишком тихо. Даже собаки не лают.',
        time_msg_deepNight_5: 'Мне кажется, я видела тень в коридоре.',
        time_msg_deepNight_6: 'В это время суток реальность и кошмар сливаются.',
        time_msg_earlyMorning_0: 'Кажется, всё стихло. Может быть, сегодня будет спокойно.',
        time_msg_earlyMorning_1: 'Я задремала на полчаса. Приснился кошмар.',
        time_msg_earlyMorning_2: 'Солнце скоро встанет. При свете всегда легче.',
        time_msg_earlyMorning_3: 'Кофе? Я бы сейчас выпила литр кофе.',
        time_msg_earlyMorning_4: 'Птицы начинают петь. Это хороший знак, правда?',
        time_msg_earlyMorning_5: 'Ещё немного — и ночь закончится. Я дожила до утра.',
        time_msg_morning_0: 'Доброе утро. Я проверила дверь — всё на месте.',
        time_msg_morning_1: 'Мне нужно на учёбу. Напишу позже.',
        time_msg_morning_2: 'При свете дня всё кажется глупым. Может, я просто параноик?',
        time_msg_morning_3: 'Спасибо, что был(а) со мной этой ночью.',
        time_msg_morning_4: 'Я попробую вести себя нормально сегодня.',
        time_msg_morning_5: 'На лекции. Профессор рассказывает про криминальную журналистику. Ирония.',
        time_msg_day_0: 'Я в библиотеке. Здесь безопасно. Много людей.',
        time_msg_day_1: 'Нашла кое-что интересное про дом 7.',
        time_msg_day_2: 'Обедаю. Аппетита нет, но надо есть.',
        time_msg_day_3: 'Позвонила Кате. Она говорит, я преувеличиваю.',
        time_msg_day_4: 'Днём этот район выглядит почти нормально.',
        time_msg_day_5: 'Проверила новости. Ничего подозрительного. Пока.',
        time_msg_evening_0: 'Солнце садится. Я чувствую, как страх возвращается.',
        time_msg_evening_1: 'Пора домой. Не хочу идти одна.',
        time_msg_evening_2: 'Снова этот вечер. Каждый раз как приговор.',
        time_msg_evening_3: 'Стемнеет через час. Я уже начинаю нервничать.',
        time_msg_evening_4: 'На улице тихо. Слишком тихо для вечера.',
        time_msg_evening_5: 'Я купила новый замок. Надеюсь, поможет.',
        time_msg_earlyNight_0: 'Уже темно. Я слышу те же звуки, что и вчера.',
        time_msg_earlyNight_1: 'Сижу дома. Все двери заперты.',
        time_msg_earlyNight_2: 'Катя не отвечает. Надеюсь, с ней всё в порядке.',
        time_msg_earlyNight_3: 'Он знает, что я дома. Я уверена.',
        time_msg_earlyNight_4: 'Соседи говорят, я всё придумываю. Но я не сумасшедшая.',
    
