        diary_d0_date: '1 мая',
        diary_d0_title: 'Всё началось',
        diary_d0_text: 'Сегодня я заметила, что кто-то следит за мной. Сначала думала — показалось. Но вечером, когда возвращалась из библиотеки, увидела одну и ту же машину три раза. Может, совпадение?',
