        diary_d3_title: 'Ночной шум',
        diary_d3_text: 'Ночью кто-то ходил под окнами. Я слышала шаги. Чёткие, тяжёлые. И скрип. Кто-то проверял дверь. Я заперлась в ванной и просидела там до утра.',
        diary_d4_date: '8 мая',
        diary_d4_title: 'Расследование',
        diary_d4_text: 'Пошла в библиотеку, подняла старые газеты. Улица Тихая, дом 7 — здесь уже пропадали люди. ТРИ ЧЕЛОВЕКА. И никто не связал это? Или не захотел связывать?',
        diary_d5_date: '9 мая',
        diary_d5_title: 'Я нашла его',
        diary_d5_text: 'Я знаю, кто это. Он работает в полиции. Поэтому все заявления игнорируются. Поэтому никто не ищет пропавших.\n\nЕсли со мной что-то случится — проверьте дежурную часть отделения №4.',
        diary_d6_date: '9 мая · позже',
        diary_d6_title: 'ПОСЛЕДНЯЯ ЗАПИСЬ',
        diary_d6_text: 'ОН ЗДЕСЬ. Слышу, как открывается дверь. Я спрятала телефон.\n\nЕсли ты читаешь это — МИША, БЕГИ. Он знает про тебя.',
    
