        katya_fallback: 'Hey! It\'s Katya. I wanted to talk about house No. 7.',
        mama_1: 'Sweetie, did you eat? Stuck in your phone again?',
        mama_2: 'Come by on Sunday for borscht. And don\'t forget your hat!',
        generic_greeting_0: 'Hey! Good to see you.',
        generic_greeting_1: 'How are you? It\'s been a while.',
        generic_greeting_2: 'Hi! What\'s new?',
        generic_greeting_3: 'Oh, hi! How\'s life?',
    
        anna_v_name: 'Anna V.',
        time_msg_lateNight_0: 'I can\'t sleep... those sounds outside the window again.',
        time_msg_lateNight_1: 'Sorry it\'s so late. I just need to talk to someone.',
        time_msg_lateNight_2: 'You\'re awake too? I feel like I\'m losing my mind.',
        time_msg_lateNight_3: 'Three in the morning is always the scariest time...',
        time_msg_lateNight_4: 'Do you hear that? That creak. It\'s back.',
        time_msg_lateNight_5: 'I\'m afraid to close my eyes. What if I don\'t wake up?',
        time_msg_lateNight_6: 'At night every sound feels louder. Even my own heartbeat.',
        time_msg_lateNight_7: 'Look out the window. See that streetlight? It\'s been flickering for an hour.',
        time_msg_deepNight_0: 'Three in the morning. They say it\'s the demons\' hour.',
        time_msg_deepNight_1: 'I heard footsteps on the stairs. Right now. Just now.',
        time_msg_deepNight_2: 'Awake? I\'m scared. Really scared.',
        time_msg_deepNight_3: 'Someone tried the door. I heard the handle creak.',
        time_msg_deepNight_4: 'Silence... too quiet. Even the dogs aren\'t barking.',
        time_msg_deepNight_5: 'I think I saw a shadow in the hallway.',
        time_msg_deepNight_6: 'At this hour, reality and nightmare blur together.',
        time_msg_earlyMorning_0: 'Seems like it\'s all quieted down. Maybe today will be calm.',
        time_msg_earlyMorning_1: 'I dozed off for half an hour. Had a nightmare.',
        time_msg_earlyMorning_2: 'The sun will rise soon. Everything\'s easier in the light.',
        time_msg_earlyMorning_3: 'Coffee? I could drink a whole pot right now.',
        time_msg_earlyMorning_4: 'The birds are starting to sing. That\'s a good sign, right?',
        time_msg_earlyMorning_5: 'Just a little longer and the night will be over. I made it to morning.',
        time_msg_morning_0: 'Good morning. I checked the door — everything\'s fine.',
        time_msg_morning_1: 'I have to go to class. I\'ll write later.',
        time_msg_morning_2: 'In daylight everything feels silly. Maybe I\'m just paranoid?',
        time_msg_morning_3: 'Thank you for being with me last night.',
        time_msg_morning_4: 'I\'ll try to act normal today.',
        time_msg_morning_5: 'In class. The professor is talking about crime journalism. Ironic.',
        time_msg_day_0: 'I\'m at the library. It\'s safe here. Lots of people.',
        time_msg_day_1: 'Found something interesting about house No. 7.',
        time_msg_day_2: 'Having lunch. No appetite, but I have to eat.',
        time_msg_day_3: 'Called Katya. She says I\'m exaggerating.',
        time_msg_day_4: 'This neighborhood looks almost normal during the day.',
        time_msg_day_5: 'Checked the news. Nothing suspicious. So far.',
        time_msg_evening_0: 'The sun is setting. I can feel the fear coming back.',
        time_msg_evening_1: 'Time to go home. I don\'t want to walk alone.',
        time_msg_evening_2: 'This evening again. Every time it feels like a sentence.',
        time_msg_evening_3: 'It\'ll be dark in an hour. I\'m already getting nervous.',
        time_msg_evening_4: 'It\'s quiet outside. Too quiet for an evening.',
        time_msg_evening_5: 'I bought a new lock. Hope it helps.',
        time_msg_earlyNight_0: 'It\'s dark already. I hear the same sounds as yesterday.',
        time_msg_earlyNight_1: 'Sitting at home. All the doors are locked.',
        time_msg_earlyNight_2: 'Katya isn\'t answering. I hope she\'s okay.',
        time_msg_earlyNight_3: 'He knows I\'m home. I\'m sure of it.',
        time_msg_earlyNight_4: 'The neighbors say I\'m making it all up. But I\'m not crazy.',
    
        game_start_date: 'November 9 · 11:41 PM',
