        clue_c1_title: 'Note by the door',
        clue_c1_desc: '"I know you\'re home. Don\'t come out." — found on May 9th under the door.',
        clue_c2_title: 'Photo of a silhouette',
        clue_c2_desc: 'A blurry figure by the entrance. Taken automatically at 11:17 PM.',
        clue_c3_title: 'Newspaper clipping',
        clue_c3_desc: 'An article about the disappearance of Viktor Strelnikov. March of last year.',
        clue_c4_title: 'Resident list',
        clue_c4_desc: 'Three people have vanished from house No. 7. Strelnikov, the Ivanovs. Anna would be the fourth.',
        clue_c5_title: 'Voice recorder clip',
        clue_c5_desc: 'Anna mentions that her stalker works for the police.',
        clue_c6_title: 'Duty officer records',
        clue_c6_desc: 'The duty officer\'s number from the police call matches the "Watcher\'s" contact.',
        clue_c7_title: 'Address book',
        clue_c7_desc: 'Quiet Street, house No. 7 — previously belonged to someone known only as "S."',
        clue_c8_title: 'Personal file',
        clue_c8_desc: 'A secret file from the gallery. Contains compromising material on a police officer.',
    
        diary_d0_date: 'May 1',
        diary_d0_title: 'It all began',
        diary_d0_text: 'Today I noticed someone was following me. At first I thought I imagined it. But in the evening, coming back from the library, I saw the same car three times. Coincidence, maybe?',
        diary_d1_date: 'May 3',
        diary_d1_title: 'First report',
        diary_d1_text: 'Called the police. They said "come back if you have real evidence." What evidence? Am I supposed to wait until I get killed?',
        diary_d2_date: 'May 5',
        diary_d2_title: 'Katya doesn\'t believe me',
        diary_d2_text: 'Told Katya. She thinks I\'m exaggerating. "Anna, it\'s just school stress." But I know — this isn\'t stress. This is something real.',
        diary_d3_date: 'May 7',
        diary_d3_title: 'Night noise',
        diary_d3_text: 'Someone was walking under the windows at night. I heard footsteps. Clear, heavy. And a creak. Someone was checking the door. I locked myself in the bathroom and sat there until morning.',
        diary_d4_date: 'May 8',
        diary_d4_title: 'Investigation',
        diary_d4_text: 'Went to the library, dug up old newspapers. Quiet Street, house No. 7 — people have vanished here before. THREE PEOPLE. And nobody connected it? Or didn\'t want to?',
        diary_d5_date: 'May 9',
        diary_d5_title: 'I found him',
        diary_d5_text: 'I know who it is. He works for the police. That\'s why every report gets ignored. That\'s why no one looks for the missing.\n\nIf something happens to me — check the duty desk at Precinct No. 4.',
        diary_d6_date: 'May 9 · later',
        diary_d6_title: 'LAST ENTRY',
        diary_d6_text: 'HE\'S HERE. I hear the door opening. I hid my phone.\n\nIf you\'re reading this — MISHA, RUN. He knows about you.',
    
        ending_salvation_name: 'Salvation',
        ending_salvation_desc: 'Anna survived. You helped her flee the city. She started a new life somewhere else.',
        ending_tragedy_name: 'Tragedy',
        ending_tragedy_desc: 'Anna didn\'t survive. You didn\'t get to her in time. Her body was found three days later in the basement of house No. 7.',
        ending_truth_name: 'Truth',
        ending_truth_desc: 'You exposed the network. The culprit was arrested. People finally learned the truth about house No. 7.',
        ending_ghost_name: 'Ghost',
        ending_ghost_desc: 'Anna disappeared. Like the others. No one ever found her. She became just another mystery of house No. 7.',
        ending_sacrifice_name: 'Sacrifice',
        ending_sacrifice_desc: 'You sacrificed yourself for Anna. You went to house No. 7 to save her. You made it in time.',
        ending_paranoia_name: 'Paranoia',
        ending_paranoia_desc: 'Anna\'s fear drove her mad. Reality and delusion blurred together. She can no longer tell friend from foe.',
        ending_watcher_name: 'The Watcher',
        ending_watcher_desc: 'You found out who the Watcher is. And now he\'s watching you. He\'s always nearby.',
        ending_redemption_name: 'Redemption',
        ending_redemption_desc: 'You saved Anna and helped bring justice. The culprit was punished. Anna is alive.',
    
