        katya_new_chat: 'New chat: Katya',
        katya_sent_files: 'Katya sent over some files',
        katya_new_data: 'New investigation data received',
        katya_preparing_docs: 'Katya is preparing documents',
        katya_gathering_evidence: 'Katya is gathering evidence',
        katya_msg_firstContact_0: 'Hi! It\'s Katya. Anna gave me your number.',
        katya_msg_firstContact_1: 'Listen, I\'m worried about her. She\'s been... strange lately.',
        katya_msg_firstContact_2: 'Have you talked to her? Has she said anything about being followed?',
        katya_msg_worried_0: 'Anna hasn\'t answered in hours. She\'s usually always reachable.',
        katya_msg_worried_1: 'I stopped by yesterday — the door was locked, but the light was on inside.',
        katya_msg_worried_2: 'Do you know where she might have gone?',
        katya_msg_secret_0: 'Okay... there\'s something I need to tell you.',
        katya_msg_secret_1: 'I know about house No. 7. And about the people who vanished.',
        katya_msg_secret_2: 'Anna isn\'t the first. I tried to warn her, but she wouldn\'t listen.',
        katya_msg_confession_0: 'I gave her your number. Because I knew you\'d help.',
        katya_msg_confession_1: 'Sorry for dragging you into this. But I didn\'t know who else to turn to.',
        katya_msg_confession_2: 'The police are useless. They\'re part of this.',
        katya_msg_final_0: 'I did everything I could. Now it\'s up to you.',
        katya_msg_final_1: 'Anna trusts you. Don\'t let her down.',
        katya_msg_final_2: 'And remember: not all doors are meant to be opened.',
        katya_2: 'She says someone\'s following her. That someone walks around the house at night.',
        katya_5: 'The police know. But they do nothing. Because one of them... is the stalker.',
        katya_6: 'I tried to tell Anna. But she didn\'t believe me. Said I was exaggerating.',
        katya_7: 'And now... now she\'s gotten herself into it. And I don\'t know how to save her.',
        katya_3_yes: 'Thank god you believe me. I was starting to think I was losing my mind.',
        katya_4_yes: 'Listen, there\'s something else. About the house she lives in...',
        katya_3_maybe: 'You don\'t understand. This isn\'t just exhaustion. There\'s something real going on.',
        katya_4_maybe: 'I\'ve known Anna for years. She\'s not hysterical. If she says someone\'s following her — it\'s true.',
        katya_3_what: 'You want to know the truth? Fine. But you won\'t like it.',
        katya_4_what: 'Quiet Street, house No. 7. Three people have vanished from there in the last two years.',
        katya_end1_help: 'Thank you. Really, thank you. I knew you\'d help.',
        katya_end2_help: 'I have some notes. And addresses. I\'ll send them to you.',
        katya_end1_police: 'You\'re right. But be careful. He works at Precinct No. 4.',
        katya_end2_police: 'I\'ll gather everything I have. Let\'s meet tomorrow.',
        kat_yes: 'Yes, she wrote to me. This looks serious.',
        kat_maybe: 'Maybe she\'s just overtired?',
        kat_what: 'What do you know about this? Tell me.',
        kat_help: 'We\'ll save her. Together.',
        kat_police: 'We need to go to the prosecutor\'s office. Gather all the evidence.',
    
