        gallery_g0_title: 'House No. 7',
        gallery_g0_desc: 'A gray five-story panel building on Quiet Street. House No. 7. This is where Anna lives.',
        gallery_g1_title: 'Entrance',
        gallery_g1_desc: 'The dark entryway of house No. 7. Peeling paint. A smell of damp. Is someone standing in the corner?',
        gallery_g2_title: 'Mailboxes',
        gallery_g2_desc: 'Old mailboxes. One of them reads "Voronina." Apartment 14.',
        gallery_g3_title: 'Door of apartment 14',
        gallery_g3_desc: 'Anna\'s apartment door. Old, peeling paint. Fresh scratches at eye level.',
        gallery_g4_title: 'Empty courtyard',
        gallery_g4_desc: 'The courtyard of house No. 7. Gray sky. Bare trees. Not a soul. Too quiet for an evening.',
        gallery_g5_title: 'Boot prints',
        gallery_g5_desc: 'Muddy footprints on the entryway floor. Leading to apartment 14. Size 10-11. Men\'s.',
        gallery_g6_title: 'Broken window',
        gallery_g6_desc: 'A window in the entryway is broken. Shards on the floor. The way to the basement is open now.',
        gallery_g7_title: 'Streetlight with a camera',
        gallery_g7_desc: 'A streetlamp by the house. A surveillance camera mounted on it. Someone\'s shadow beneath the light.',
        gallery_g8_title: 'Note with a number',
        gallery_g8_desc: 'A note on the entrance door: "You\'re not alone. Call me. +7 (999) 123-45-67"',
        gallery_g9_title: 'Blood drops',
        gallery_g9_desc: 'Dark stains on the hallway floor. Look like blood. Leading to apartment 16.',
        gallery_g10_title: 'Stranger in frame',
        gallery_g10_desc: 'A blurry silhouette of a person in the window across the way. Looking straight at the camera.',
        gallery_g11_title: 'Car plate',
        gallery_g11_desc: 'A Lada 2106 with plate A123BB. Constantly parked by house No. 7.',
        gallery_g12_title: 'The clock at 3:00',
        gallery_g12_desc: 'A wall clock in the entryway. The hands read exactly 3:00. The time of the disappearances.',
        gallery_g13_title: 'Reflection in the window',
        gallery_g13_desc: 'A photo of apartment 14\'s window. A person\'s silhouette is visible in the reflection. He\'s inside.',
        gallery_g14_title: 'Silhouette on the roof',
        gallery_g14_desc: 'A night photo of the roof. A person\'s silhouette on it. He\'s looking down at the street.',
