        gallery_g15_desc: 'A Russian passport in the name of Voronina Anna Sergeyevna. Partially hidden.',
        gallery_g16_title: 'Police report',
        gallery_g16_desc: 'An interrogation report on the disappearance case. Signature: Major Strelnikov.',
        gallery_g17_title: 'Building plan',
        gallery_g17_desc: 'The floor plan of house No. 7. Apartment 14 is in the center. All exits marked in red.',
