        search_label: 'SEARCH',
        article_a1_title: 'Young woman vanishes after going to the police',
        article_a1_desc: 'Anna V. went to the police two weeks before her disappearance...',
        article_a1_full: 'Full article on the disappearance of Anna Voronina. The young woman had repeatedly gone to the police, but wasn\'t believed. She was last seen on May 9th near house No. 7 on Quiet Street. Police declined to comment on the case.',
        article_a2_title: 'How to tell paranoia from a real threat',
        article_a2_desc: 'Sometimes fear is justified. Sometimes it\'s a symptom.',
        article_a2_full: 'Psychologists discuss the signs of a real threat versus paranoia. Experts note that in Anna Voronina\'s case, all the signs pointed to real danger, not a mental disorder.',
        article_a3_title: 'Who is the "Watcher"?',
        article_a3_desc: 'Urban legend or a real surveillance network?',
        article_a3_full: 'An investigation into a mysterious surveillance network. Local residents claim the "Watcher" is a person keeping tabs on the residents of house No. 7. Rumor has it he\'s a former police officer.',
        article_a4_title: 'Disappearances on Quiet Street: a timeline',
        article_a4_desc: 'Three people have vanished in two years.',
        article_a4_full: 'Timeline of disappearances on Quiet Street:\n\n• March 2023 — Viktor Strelnikov\n• August 2023 — The Ivanov family (2 people)\n• May 2024 — Anna Voronina (missing)\n\nAll disappearances are linked to house No. 7.',
        article_a5_title: 'Cat hacks the Pentagon: a true story',
        article_a5_desc: 'A British cat accidentally triggered a nuclear alert.',
        article_a5_full: 'A funny story about a hacker cat that walked across a keyboard and nearly started World War III. The cat\'s name was Whiskers, and he just wanted food.',
        article_a6_title: 'Grandma beats Dark Souls: a record',
        article_a6_desc: 'An 83-year-old retiree surprises the world.',
        article_a6_full: '"Well, it was pretty tough," says grandma. She beat the game in 120 hours, using only one hand. Now she\'s planning to tackle Sekiro.',
        article_a7_title: 'Top 10 ways to avoid being followed',
        article_a7_desc: 'Advice from cybersecurity experts.',
        article_a7_full: 'Experts share cybersecurity tips. Special attention is given to protecting yourself from surveillance in urban environments. It\'s recommended to vary your routes and use encrypted apps.',
    
        note_n1_title: '📋 To-do list',
        note_n1_body: '— Buy bread\n— Call the doctor\n— Don\'t forget to feed the cat\n\n[Added later]\nDON\'T OPEN THE DOOR\nTHEY\'RE ALREADY HERE',
        note_n1_date: 'May 9',
        note_n2_title: '🔒 Important [encrypted]',
        note_n2_body: 'The file is encrypted.\nIf you\'re reading this — I didn\'t make it in time.\nPassword: 2305\n\nShe was watching you.\n— Katya',
        note_n2_date: 'May 7',
        note_n3_title: '😂 Fun fact',
        note_n3_body: 'Why do programmers mix up Christmas and Halloween?\n\nBecause 25 Dec = 31 Oct!\n\n(if you got it — you\'re a legend)',
        note_n3_date: 'April 1',
        note_n4_title: '📝 Lecture notes',
        note_n4_body: 'Topic: investigative journalism\n\nImportant: always verify sources.\nIf someone says "I feel like" — that\'s not a source.\n\nAnna was at this lecture.',
        note_n4_date: 'May 3',
        note_n5_title: '📞 Important numbers',
        note_n5_body: 'Anna: +7 (999) 123-45-67\nKatya: +7 (999) 234-56-78\nMom: +7 (999) 345-67-89\nViktor (police): +7 (999) 901-23-45\n\nSave to your phone.',
        note_n5_date: 'May 5',
        note_n6_title: '🔍 Clues',
        note_n6_body: '1. Note by the door\n2. Photo of a silhouette\n3. Newspaper clipping (Strelnikov)\n4. Resident list\n5. Voice recorder clip\n6. Duty officer records\n7. Address book\n8. Personal file',
        note_n6_date: 'May 8',
    
        dict_rec1_title: 'Night noise',
        dict_rec1_date: 'May 7 · 2:34 AM',
        dict_rec1_line0: 'I don\'t know why I\'m recording this...',
        dict_rec1_line1: '[floorboards creaking]',
        dict_rec1_line2: 'That sound again. Third time tonight.',
        dict_rec1_line3: '[15-second pause]',
        dict_rec1_line4: 'If anyone finds this recording... my name is Anna Voronina. I live on Quiet Street, house No. 7.',
        dict_rec1_line5: '[loud bang, recording cuts off]',
        dict_rec1_note: 'Recording automatically uploaded to the cloud. Location: 7 Quiet Street.',
        dict_rec2_title: 'Call with Katya',
        dict_rec2_date: 'May 6 · 7:15 PM',
        dict_rec2_line0: 'Katya, can you hear me? The connection is terrible.',
        dict_rec2_line1: 'Yes, I hear you. What\'s wrong? You sound upset.',
        dict_rec2_line2: 'I think someone\'s following me. It\'s been a week.',
        dict_rec2_line3: 'Again? Anna, we\'ve talked about this. You\'re working yourself up.',
        dict_rec2_line4: 'No, this time it\'s serious! I saw a man by the entrance. He was standing there staring at my windows.',
        dict_rec2_line5: 'Maybe it was just a neighbor? Or someone waiting for a cab?',
        dict_rec2_line6: 'At three in the morning? Katya, please believe me.',
        dict_rec2_line7: 'Okay... let\'s say I do. What do you want me to do?',
        dict_rec2_line8: 'You said you know someone... Misha? Who\'s good with this kind of thing.',
        dict_rec2_line9: '[pause] Yes, I do. But he\'s... a peculiar guy.',
        dict_rec2_line10: 'Give me his number. Please.',
        dict_rec2_line11: 'Alright. But be careful. And... Anna? Don\'t do anything stupid.',
        dict_rec2_note: 'Katya sent Misha\'s number an hour after the call.',
        dict_rec3_title: 'Additional recording',
        dict_rec3_date: 'May 8 · 11:57 PM',
        dict_rec3_line0: 'I did some digging. House number seven on Quiet Street.',
        dict_rec3_line1: '[papers rustling]',
        dict_rec3_line2: 'Three people have vanished from here in the last two years. THREE.',
        dict_rec3_line3: 'And the police did nothing. They didn\'t even look.',
        dict_rec3_line4: 'The first was Strelnikov, Viktor. Vanished in March. The second, a young couple, the Ivanovs. Disappeared in August.',
        dict_rec3_line5: '[long pause, breathing audible]',
        dict_rec3_line6: 'I think... I know who\'s behind this. But no one will believe me.',
        dict_rec3_line7: '[quiet whisper]',
        dict_rec3_line8: 'He works for the police. That\'s why they didn\'t find anything.',
        dict_rec3_note: 'Recording found in drafts. Was never sent.',
        dict_rec4_title: 'Last recording',
        dict_rec4_date: 'May 9 · 12:13 AM',
        dict_rec4_line0: 'He\'s here. I hear the door opening.',
        dict_rec4_line1: '[crash, scream]',
        dict_rec4_line2: 'Please... don\'t...',
        dict_rec4_line3: '[sound of a struggle]',
        dict_rec4_line4: 'You know too much, Anna.',
        dict_rec4_line5: '[recording cuts off]',
        dict_rec4_note: 'RECORDING RECOVERED FROM CLOUD STORAGE. Last accessed: May 9, 12:13 AM.',
        dict_rec5_title: 'Call to the police',
        dict_rec5_date: 'May 5 · 2:22 PM',
        dict_rec5_line0: 'Duty desk, go ahead.',
        dict_rec5_line1: 'Hello, my name is Anna Voronina. I want to report being followed.',
        dict_rec5_line2: 'State your address.',
        dict_rec5_line3: 'Quiet Street, house No. 7, apartment 14.',
        dict_rec5_line4: '[long pause]',
        dict_rec5_line5: '...Did you say house seven?',
        dict_rec5_line6: 'Yes. Why?',
        dict_rec5_line7: 'No reason. File a report by phone or come to the station.',
