        katya_fallback: '¡Hola! Soy Katya. Quería hablar sobre la casa n.º 7.',
        mama_1: 'Hijo, ¿ya comiste? ¿Otra vez pegado al teléfono?',
        mama_2: 'Ven el domingo a comer borsch. ¡Y no olvides ponerte el gorro!',
        generic_greeting_0: '¡Hola! Qué bueno verte.',
        generic_greeting_1: '¿Cómo estás? Cuánto tiempo sin hablar.',
        generic_greeting_2: '¡Hola! ¿Qué hay de nuevo?',
        generic_greeting_3: '¡Ah, hola! ¿Cómo va la vida?',
    
        anna_v_name: 'Ana V.',
        time_msg_lateNight_0: 'No puedo dormir... otra vez esos sonidos afuera de la ventana.',
        time_msg_lateNight_1: 'Perdón por la hora. Solo necesito hablar con alguien.',
        time_msg_lateNight_2: '¿Tú tampoco duermes? Siento que estoy perdiendo la cabeza.',
        time_msg_lateNight_3: 'Las tres de la madrugada siempre son la hora más terrible...',
        time_msg_lateNight_4: '¿Oyes eso? Ese crujido. Volvió.',
        time_msg_lateNight_5: 'Tengo miedo de cerrar los ojos. ¿Y si no despierto?',
        time_msg_lateNight_6: 'De noche todos los sonidos parecen más fuertes. Hasta mi propio corazón.',
        time_msg_lateNight_7: 'Mira por la ventana. ¿Ves esa farola? Lleva una hora parpadeando.',
        time_msg_deepNight_0: 'Las tres de la madrugada. Dicen que es la hora de los demonios.',
        time_msg_deepNight_1: 'Oí pasos en la escalera. Ahora mismo. Justo ahora.',
        time_msg_deepNight_2: '¿Despierto? Tengo miedo. Mucho miedo.',
        time_msg_deepNight_3: 'Alguien probó la puerta. Oí crujir la manija.',
        time_msg_deepNight_4: 'Silencio... demasiado silencio. Ni los perros ladran.',
        time_msg_deepNight_5: 'Creo que vi una sombra en el pasillo.',
        time_msg_deepNight_6: 'A esta hora la realidad y la pesadilla se mezclan.',
        time_msg_earlyMorning_0: 'Parece que todo se calmó. Quizás hoy sea tranquilo.',
        time_msg_earlyMorning_1: 'Me quedé dormida media hora. Tuve una pesadilla.',
        time_msg_earlyMorning_2: 'El sol saldrá pronto. Con luz todo es más fácil.',
        time_msg_earlyMorning_3: '¿Café? Ahora mismo me tomaría un litro.',
        time_msg_earlyMorning_4: 'Los pájaros empiezan a cantar. Eso es buena señal, ¿no?',
        time_msg_earlyMorning_5: 'Un poco más y la noche terminará. Sobreviví hasta la mañana.',
        time_msg_morning_0: 'Buenos días. Revisé la puerta, todo está en su lugar.',
        time_msg_morning_1: 'Tengo que ir a clase. Te escribo luego.',
        time_msg_morning_2: 'Con la luz del día todo parece una tontería. ¿Seré solo paranoica?',
        time_msg_morning_3: 'Gracias por estar conmigo anoche.',
        time_msg_morning_4: 'Voy a intentar actuar normal hoy.',
        time_msg_morning_5: 'En clase. El profesor habla de periodismo criminal. Qué ironía.',
        time_msg_day_0: 'Estoy en la biblioteca. Aquí se está a salvo. Hay mucha gente.',
        time_msg_day_1: 'Encontré algo interesante sobre la casa 7.',
        time_msg_day_2: 'Almorzando. No tengo apetito, pero hay que comer.',
        time_msg_day_3: 'Llamé a Katya. Dice que estoy exagerando.',
        time_msg_day_4: 'De día este barrio se ve casi normal.',
        time_msg_day_5: 'Revisé las noticias. Nada sospechoso. Por ahora.',
        time_msg_evening_0: 'El sol se pone. Siento que el miedo vuelve.',
        time_msg_evening_1: 'Hora de ir a casa. No quiero ir sola.',
        time_msg_evening_2: 'Otra vez esta noche. Cada vez se siente como una condena.',
        time_msg_evening_3: 'Oscurecerá en una hora. Ya empiezo a ponerme nerviosa.',
        time_msg_evening_4: 'Está tranquilo afuera. Demasiado tranquilo para un atardecer.',
        time_msg_evening_5: 'Compré una cerradura nueva. Espero que ayude.',
        time_msg_earlyNight_0: 'Ya está oscuro. Oigo los mismos sonidos que ayer.',
        time_msg_earlyNight_1: 'Estoy en casa. Todas las puertas están cerradas con llave.',
        time_msg_earlyNight_2: 'Katya no responde. Espero que esté bien.',
        time_msg_earlyNight_3: 'Sabe que estoy en casa. Estoy segura.',
        time_msg_earlyNight_4: 'Los vecinos dicen que me lo invento todo. Pero no estoy loca.',
    
