        clue_c1_title: 'Nota junto a la puerta',
        clue_c1_desc: '"Sé que estás en casa. No salgas." — encontrada el 9 de mayo bajo la puerta.',
        clue_c2_title: 'Foto de una silueta',
        clue_c2_desc: 'Una figura borrosa junto a la entrada. Tomada automáticamente a las 23:17.',
        clue_c3_title: 'Recorte de periódico',
        clue_c3_desc: 'Un artículo sobre la desaparición de Víktor Strélnikov. Marzo del año pasado.',
        clue_c4_title: 'Lista de residentes',
        clue_c4_desc: 'Tres personas han desaparecido de la casa 7. Strélnikov, los Ivanov. Ana sería la cuarta.',
        clue_c5_title: 'Grabación de la dictáfono',
        clue_c5_desc: 'Ana menciona que su acosador trabaja en la policía.',
        clue_c6_title: 'Registro del oficial de guardia',
        clue_c6_desc: 'El número del oficial de guardia de la llamada a la policía coincide con el contacto del "Observador".',
        clue_c7_title: 'Libreta de direcciones',
        clue_c7_desc: 'Calle Tijaya, casa 7 — perteneció antes a alguien conocido solo como "S."',
        clue_c8_title: 'Expediente personal',
        clue_c8_desc: 'Un archivo secreto de la galería. Contiene material comprometedor sobre un oficial de policía.',
    
        diary_d0_date: '1 de mayo',
        diary_d0_title: 'Todo empezó',
        diary_d0_text: 'Hoy noté que alguien me seguía. Al principio pensé que lo imaginaba. Pero por la tarde, al volver de la biblioteca, vi el mismo coche tres veces. ¿Coincidencia, quizás?',
        diary_d1_date: '3 de mayo',
        diary_d1_title: 'Primera denuncia',
        diary_d1_text: 'Llamé a la policía. Dijeron "vuelva si tiene pruebas reales". ¿Qué pruebas? ¿Debo esperar a que me maten?',
        diary_d2_date: '5 de mayo',
        diary_d2_title: 'Katya no me cree',
        diary_d2_text: 'Se lo conté a Katya. Cree que exagero. "Ana, es solo el estrés de los estudios". Pero yo sé que no es estrés. Es algo real.',
        diary_d3_date: '7 de mayo',
        diary_d3_title: 'Ruido nocturno',
        diary_d3_text: 'Por la noche alguien caminaba bajo las ventanas. Oí pasos. Claros, pesados. Y un crujido. Alguien probaba la puerta. Me encerré en el baño y me quedé ahí hasta la mañana.',
        diary_d4_date: '8 de mayo',
        diary_d4_title: 'Investigación',
        diary_d4_text: 'Fui a la biblioteca, busqué periódicos viejos. Calle Tijaya, casa 7: aquí ya han desaparecido personas. TRES PERSONAS. ¿Y nadie lo relacionó? ¿O no quiso hacerlo?',
        diary_d5_date: '9 de mayo',
        diary_d5_title: 'Lo encontré',
        diary_d5_text: 'Sé quién es. Trabaja en la policía. Por eso ignoran todas las denuncias. Por eso nadie busca a los desaparecidos.\n\nSi me pasa algo, revisen la guardia de la comisaría n.º 4.',
        diary_d6_date: '9 de mayo · más tarde',
        diary_d6_title: 'ÚLTIMA ENTRADA',
        diary_d6_text: 'ESTÁ AQUÍ. Oigo que se abre la puerta. Escondí el teléfono.\n\nSi estás leyendo esto — MISHA, CORRE. Sabe de ti.',
    
        ending_salvation_name: 'Salvación',
        ending_salvation_desc: 'Ana sobrevivió. La ayudaste a huir de la ciudad. Empezó una nueva vida en otro lugar.',
        ending_tragedy_name: 'Tragedia',
        ending_tragedy_desc: 'Ana no sobrevivió. No llegaste a tiempo para ayudarla. Encontraron su cuerpo tres días después en el sótano de la casa n.º 7.',
        ending_truth_name: 'Verdad',
        ending_truth_desc: 'Destapaste la red criminal. El culpable fue arrestado. La gente finalmente conoció la verdad sobre la casa n.º 7.',
        ending_ghost_name: 'Fantasma',
        ending_ghost_desc: 'Ana desapareció. Como los demás. Nadie la encontró nunca. Se convirtió en otro misterio más de la casa n.º 7.',
        ending_sacrifice_name: 'Sacrificio',
        ending_sacrifice_desc: 'Te sacrificaste por Ana. Fuiste a la casa n.º 7 para salvarla. Llegaste a tiempo.',
        ending_paranoia_name: 'Paranoia',
        ending_paranoia_desc: 'El miedo enloqueció a Ana. La realidad y la fantasía se mezclaron. Ya no distingue entre amigos y enemigos.',
        ending_watcher_name: 'El Observador',
        ending_watcher_desc: 'Descubriste quién es el Observador. Y ahora él te vigila a ti. Siempre está cerca.',
        ending_redemption_name: 'Redención',
        ending_redemption_desc: 'Salvaste a Ana y ayudaste a hacer justicia. El culpable fue castigado. Ana está viva.',
    
