        katya_msg_worried_0: 'Ana no responde desde hace horas. Normalmente siempre está disponible.',
        katya_msg_worried_1: 'Pasé por su casa ayer: la puerta estaba cerrada, pero había luz adentro.',
        katya_msg_worried_2: '¿Sabes a dónde pudo haber ido?',
        katya_msg_secret_0: 'Bueno... tengo que contarte algo.',
        katya_msg_secret_1: 'Sé lo de la casa 7. Y lo de la gente que desapareció.',
        katya_msg_secret_2: 'Ana no es la primera. Intenté advertirle, pero no me escuchó.',
        katya_msg_confession_0: 'Yo le di tu número. Porque sabía que ayudarías.',
        katya_msg_confession_1: 'Perdón por meterte en esto. Pero no sabía a quién más recurrir.',
        katya_msg_confession_2: 'La policía es inútil. Son parte de esto.',
        katya_msg_final_0: 'Hice todo lo que pude. Ahora depende de ti.',
