        katya_msg_final_2: 'Y recuerda: no todas las puertas deben abrirse.',
        katya_2: 'Dice que alguien la sigue. Que alguien camina alrededor de la casa por las noches.',
        katya_5: 'La policía lo sabe. Pero no hacen nada. Porque uno de ellos... es el acosador.',
        katya_6: 'Intenté contarle a Ana. Pero no me creyó. Dijo que estaba exagerando.',
        katya_7: 'Y ahora... ahora ella misma se metió en esto. Y no sé cómo salvarla.',
