        search_label: 'BÚSQUEDA',
        article_a1_title: 'Joven desaparece tras acudir a la policía',
        article_a1_desc: 'Ana V. acudió a la policía dos semanas antes de desaparecer...',
        article_a1_full: 'Artículo completo sobre la desaparición de Ana Voronina. La joven había acudido varias veces a la policía, pero no le creyeron. Fue vista por última vez el 9 de mayo cerca de la casa n.º 7 en la calle Tijaya. La policía se negó a comentar el caso.',
        article_a2_title: 'Cómo distinguir la paranoia de una amenaza real',
        article_a2_desc: 'A veces el miedo está justificado. A veces es un síntoma.',
        article_a2_full: 'Psicólogos hablan sobre las señales de una amenaza real frente a la paranoia. Los expertos señalan que en el caso de Ana Voronina todas las señales apuntaban a un peligro real, no a un trastorno mental.',
        article_a3_title: '¿Quién es el «Observador»?',
        article_a3_desc: '¿Leyenda urbana o una red de vigilancia real?',
        article_a3_full: 'Una investigación sobre una misteriosa red de vigilancia. Vecinos afirman que el "Observador" es una persona que vigila a los residentes de la casa n.º 7. Según los rumores, es un expolicía.',
        article_a4_title: 'Desapariciones en la calle Tijaya: cronología',
        article_a4_desc: 'Tres personas han desaparecido en dos años.',
        article_a4_full: 'Cronología de las desapariciones en la calle Tijaya:\n\n• Marzo de 2023 — Víktor Strélnikov\n• Agosto de 2023 — La familia Ivanov (2 personas)\n• Mayo de 2024 — Ana Voronina (desaparecida)\n\nTodas las desapariciones están vinculadas a la casa n.º 7.',
        article_a5_title: 'Un gato hackea el Pentágono: una historia real',
        article_a5_desc: 'Un gato británico activó por accidente una alerta nuclear.',
        article_a5_full: 'Una divertida historia sobre un gato hacker que caminó sobre un teclado y casi desató la Tercera Guerra Mundial. El gato se llamaba Bigotes y solo quería comer.',
        article_a6_title: 'Una abuela completa Dark Souls: un récord',
        article_a6_desc: 'Una jubilada de 83 años sorprende al mundo.',
        article_a6_full: '"Bueno, fue bastante difícil", dice la abuela. Completó el juego en 120 horas usando solo una mano. Ahora planea jugar Sekiro.',
        article_a7_title: 'Top 10 formas de evitar que te sigan',
        article_a7_desc: 'Consejos de expertos en ciberseguridad.',
        article_a7_full: 'Los expertos comparten consejos de ciberseguridad. Se presta especial atención a protegerse de la vigilancia en entornos urbanos. Se recomienda variar las rutas y usar aplicaciones cifradas.',
    
        note_n1_title: '📋 Lista de tareas',
        note_n1_body: '— Comprar pan\n— Llamar al médico\n— No olvidar alimentar al gato\n\n[Añadido después]\nNO ABRAS LA PUERTA\nYA ESTÁN AQUÍ',
        note_n1_date: '9 de mayo',
        note_n2_title: '🔒 Importante [cifrado]',
        note_n2_body: 'El archivo está cifrado.\nSi estás leyendo esto, no llegué a tiempo.\nContraseña: 2305\n\nElla te vigilaba.\n— Katya',
        note_n2_date: '7 de mayo',
        note_n3_title: '😂 Dato curioso',
        note_n3_body: '¿Por qué los programadores confunden Navidad y Halloween?\n\n¡Porque 25 Dec = 31 Oct!\n\n(si lo entendiste, eres una leyenda)',
        note_n3_date: '1 de abril',
        note_n4_title: '📝 Apuntes de clase',
        note_n4_body: 'Tema: periodismo de investigación\n\nImportante: verificar siempre las fuentes.\nSi alguien dice "tengo la sensación", eso no es una fuente.\n\nAna estuvo en esta clase.',
        note_n4_date: '3 de mayo',
        note_n5_title: '📞 Números importantes',
        note_n5_body: 'Ana: +7 (999) 123-45-67\nKatya: +7 (999) 234-56-78\nMamá: +7 (999) 345-67-89\nVíctor (policía): +7 (999) 901-23-45\n\nGuárdalos en el teléfono.',
        note_n5_date: '5 de mayo',
        note_n6_title: '🔍 Pistas',
        note_n6_body: '1. Nota junto a la puerta\n2. Foto de una silueta\n3. Recorte de periódico (Strélnikov)\n4. Lista de residentes\n5. Grabación de la dictáfono\n6. Registro del oficial de guardia\n7. Libreta de direcciones\n8. Expediente personal',
        note_n6_date: '8 de mayo',
    
        dict_rec1_title: 'Ruido nocturno',
        dict_rec1_date: '7 de mayo · 02:34',
