        dict_rec2_date: '6 de mayo · 19:15',
        dict_rec2_line0: 'Katya, ¿me oyes? La señal es terrible.',
        dict_rec2_line1: 'Sí, te oigo. ¿Qué pasó? Se te oye nerviosa.',
