var P = {
    trust: 30,
    fear: 10,
    stress: 20,
    dependency: 0,
    suspicion: 5,
    mentalState: 70,
    paranoia: 15,
    guilt: 0,
    courage: 0,
    truth: 0
};

function resetP() {
    P.trust = 30;
    P.fear = 10;
    P.stress = 20;
    P.dependency = 0;
    P.suspicion = 5;
    P.mentalState = 70;
    P.paranoia = 15;
    P.guilt = 0;
    P.courage = 0;
    P.truth = 0;
}

function adj(stats) {
    for (var key in stats) {
        if (P[key] !== undefined) {
            P[key] = Math.max(0, Math.min(100, P[key] + stats[key]));
        }
    }
}

