// 4. СИСТЕМА ВРЕМЕНИ
// ═══════════════════════════════════════════════════════════════

var GameTime = {
    day: 9,
    month: 11,
    year: 2024,
    hour: 23,
    minute: 41,
    dayPeriod: 'night',
    lastTick: Date.now(),
    paused: false,
    speed: 1,
    interval: null,
    
    days: {
        ru: ['ВОСКРЕСЕНЬЕ', 'ПОНЕДЕЛЬНИК', 'ВТОРНИК', 'СРЕДА', 'ЧЕТВЕРГ', 'ПЯТНИЦА', 'СУББОТА'],
        en: ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'],
        es: ['DOMINGO', 'LUNES', 'MARTES', 'MIÉRCOLES', 'JUEVES', 'VIERNES', 'SÁBADO']
    },
    months: {
        ru: ['ЯНВАРЯ', 'ФЕВРАЛЯ', 'МАРТА', 'АПРЕЛЯ', 'МАЯ', 'ИЮНЯ', 'ИЮЛЯ', 'АВГУСТА', 'СЕНТЯБРЯ', 'ОКТЯБРЯ', 'НОЯБРЯ', 'ДЕКАБРЯ'],
        en: ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'],
        es: ['ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE']
    },
    
    start: function() {
        this.load();
        this.updateAllDisplays();
        if (this.interval) clearInterval(this.interval);
        this.interval = setInterval(function() {
            GameTime.tick();
        }, 1000 / this.speed);
    },
    
    tick: function() {
        if (!this.paused) {
            this.advance(1);
            this.lastTick = Date.now();
        }
    },
    
    advance: function(minutes) {
        this.minute += minutes;
        while (this.minute >= 60) {
            this.minute -= 60;
            this.hour++;
        }
        while (this.hour >= 24) {
            this.hour -= 24;
            this.day++;
            if (this.day > this.getDaysInMonth()) {
                this.day = 1;
                this.month++;
                if (this.month > 12) {
                    this.month = 1;
                    this.year++;
                }
            }
        }
        this.dayPeriod = this.getDayPeriod();
        this.updateAllDisplays();
        this.checkTimeEvents();
    },
    
    getDaysInMonth: function() {
        var days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        if (this.month === 2 && (this.year % 4 === 0 && (this.year % 100 !== 0 || this.year % 400 === 0))) {
            return 29;
        }
        return days[this.month - 1];
    },
    
    getDayPeriod: function() {
        var h = this.hour;
        if (h >= 23 || h < 5) return 'night';
        if (h >= 5 && h < 9) return 'morning';
        if (h >= 9 && h < 17) return 'day';
        if (h >= 17 && h < 20) return 'evening';
        return 'night';
    },
    
    getDayOfWeek: function() {
        var baseDate = new Date(2024, 10, 15);
        var currentDate = new Date(this.year, this.month - 1, this.day);
        var diffDays = Math.floor((currentDate - baseDate) / (24 * 60 * 60 * 1000));
        var dayIndex = ((5 + diffDays) % 7 + 7) % 7;
        return dayIndex;
    },
    
    getTimeString: function() {
        return String(this.hour).padStart(2, '0') + ':' + String(this.minute).padStart(2, '0');
    },
    
    getDateString: function() {
        var lang = currentLang || 'ru';
        var days = this.days[lang] || this.days.ru;
        var months = this.months[lang] || this.months.ru;
        return days[this.getDayOfWeek()] + ', ' + this.day + ' ' + months[this.month - 1];
    },
    
    getShortDateString: function() {
        var lang = currentLang || 'ru';
        var days = this.days[lang] || this.days.ru;
        var months = this.months[lang] || this.months.ru;
        return days[this.getDayOfWeek()] + ' · ' + this.day + ' ' + months[this.month - 1];
    },
    
    getTimeOfDay: function() {
        var h = this.hour;
        if (h >= 23 || h < 5) return 'night';
        if (h >= 5 && h < 12) return 'morning';
        if (h >= 12 && h < 17) return 'day';
        return 'evening';
    },
    
    isNightTime: function() {
        var h = this.hour;
        return h >= 22 || h < 5;
    },
    
    setTime: function(day, month, hour, minute) {
        this.day = day;
        this.month = month;
        this.hour = hour;
        this.minute = minute;
        this.dayPeriod = this.getDayPeriod();
        this.updateAllDisplays();
    },
    
    jumpToNight: function() {
        if (this.hour < 22) {
            this.hour = 23;
            this.minute = 15 + Math.floor(Math.random() * 30);
        } else {
            this.day++;
            if (this.day > this.getDaysInMonth()) {
                this.day = 1;
                this.month++;
                if (this.month > 12) this.month = 1;
            }
            this.hour = 23;
            this.minute = 15 + Math.floor(Math.random() * 30);
        }
        this.dayPeriod = 'night';
        this.updateAllDisplays();
    },
    
    jumpToMorning: function() {
        this.day++;
        if (this.day > this.getDaysInMonth()) {
            this.day = 1;
            this.month++;
            if (this.month > 12) this.month = 1;
        }
        this.hour = 8 + Math.floor(Math.random() * 3);
        this.minute = Math.floor(Math.random() * 60);
        this.dayPeriod = 'morning';
        this.updateAllDisplays();
    },
    
    jumpToEvening: function() {
        this.hour = 19 + Math.floor(Math.random() * 3);
        this.minute = Math.floor(Math.random() * 60);
        this.dayPeriod = 'evening';
        this.updateAllDisplays();
    },
    
    updateAllDisplays: function() {
        var time = this.getTimeString();
        var date = this.getDateString();
        var shortDate = this.getShortDateString();
        
        var timeIds = [
            'lkTime', 'lkClock', 'hmTime', 'hmClock', 'msgTime',
            'galleryTime', 'browserTime', 'contactsTime', 'notesTime',
            'settingsTime', 'cameraTime', 'authorsTime', 'dictaphoneTime',
            'mapTime', 'calcTime', 'investigationTime', 'diaryTime',
            'endingsTime', 'appstoreTime'
        ];
        
        for (var i = 0; i < timeIds.length; i++) {
            var el = document.getElementById(timeIds[i]);
            if (el) el.textContent = time;
        }
        
        var lkDate = document.getElementById('lkDate');
        if (lkDate) lkDate.textContent = date;
        
        var hmDate = document.getElementById('hmDate');
        if (hmDate) hmDate.textContent = shortDate;
        
        var lkNotifTime = document.getElementById('lkNotifTime');
        if (lkNotifTime) lkNotifTime.textContent = time;
        
        var isNight = this.isNightTime();
        document.body.classList.toggle('night-mode', isNight);
        G.isNight = isNight;
        
        var nightInd = document.getElementById('nightInd');
        if (nightInd) {
            nightInd.style.display = isNight ? 'block' : 'none';
            if (isNight) {
                nightInd.textContent = this.hour >= 2 && this.hour < 5 ? '🌑' : '🌙';
                nightInd.style.opacity = this.hour >= 2 && this.hour < 5 ? '0.3' : '0.6';
            }
        }
        
        this.save();
    },
    
    checkTimeEvents: function() {
        var h = this.hour;
        var m = this.minute;
        
        if (m === 0 && h % 3 === 0) {
            if (typeof WeatherSystem !== 'undefined') {
                WeatherSystem.changeWeather();
            }
        }
        
        if (h === 6 && m === 0 && this.dayPeriod === 'night') {
            this.onMorning();
        }
        
        if (h === 18 && m === 0 && this.dayPeriod === 'day') {
            this.onEvening();
        }
    },
    
    onMorning: function() {
        this.dayPeriod = 'morning';
        this.updateAllDisplays();
        // БАГ #2 ИСПРАВЛЕН: fallback для перевода
        showToast('☀️ ' + (t('good_morning') || 'Наступило утро'), t('system'));
        if (typeof WeatherSystem !== 'undefined') {
            WeatherSystem.changeWeather('clear');
        }
        if (G.act === 2 && typeof triggerMorningDialogue === 'function') {
            triggerMorningDialogue();
        }
    },
    
    onEvening: function() {
        this.dayPeriod = 'evening';
        this.updateAllDisplays();
        // БАГ #3 ИСПРАВЛЕН: fallback для перевода
        showToast('🌅 ' + (t('good_evening') || 'Наступает вечер'), t('system'));
    },
    
    pause: function() {
        this.paused = true;
    },
    
    resume: function() {
        this.paused = false;
        this.lastTick = Date.now();
    },
    
    save: function() {
        try {
            localStorage.setItem('nez_gametime', JSON.stringify({
                day: this.day,
                month: this.month,
                year: this.year,
                hour: this.hour,
                minute: this.minute
            }));
        } catch(e) {}
    },
    
    load: function() {
        var saved = localStorage.getItem('nez_gametime');
        if (saved) {
            try {
                var data = JSON.parse(saved);
                this.day = data.day || 9;
                this.month = data.month || 11;
                this.year = data.year || 2024;
                this.hour = data.hour || 23;
                this.minute = data.minute || 41;
            } catch(e) {
                this.resetToDefault();
            }
        } else {
            this.resetToDefault();
        }
        this.dayPeriod = this.getDayPeriod();
    },
    
    resetToDefault: function() {
        this.day = 9;
        this.month = 11;
        this.year = 2024;
        this.hour = 23;
        this.minute = 41;
        this.dayPeriod = 'night';
    },
    
    stop: function() {
        if (this.interval) {
            clearInterval(this.interval);
            this.interval = null;
        }
    }
};

function getT() {
    return GameTime.getTimeString();
}

// ═══════════════════════════════════════════════════════════════
// 5. СИСТЕМА ПОГОДЫ
// ═══════════════════════════════════════════════════════════════

var WeatherSystem = {
    current: 'rain',
    intensity: 60,
    nextChange: 0,
    interval: null,
    stormInterval: null,
    _started: false,
    
    types: ['clear', 'rain', 'storm', 'fog', 'snow'],
    
    weatherMessages: {
        rain: [
            'Слышишь дождь? Он заглушает шаги за окном.',
            'Капли стучат по подоконнику. Или это не капли?',
            'В дождь всегда труднее услышать, когда кто-то подходит.',
            'Я люблю дождь. Но не сегодня. Не этой ночью.'
        ],
        storm: [
            'Гроза! Я боюсь, что свет отключится!',
            'Молния на секунду осветила двор. Там кто-то был.',
            'Гром заглушает всё. Даже крики.',
            'Пожалуйста, не пропадай. Мне страшно одной в грозу.'
        ],
        fog: [
            'В тумане ничего не видно. Он может быть где угодно.',
            'Я выглянула в окно — белая стена. Жутко.',
            'Туман такой густой, что фонари еле светятся.',
            'Говорят, в тумане легко заблудиться. Даже рядом с домом.'
        ],
        snow: [
            'Снег скрипит под окном. Кто-то ходит.',
            'На снегу следы. Они ведут к моей двери.',
            'Всё белое... слишком чистое. Как будто что-то скрывает.',
            'Снег заглушает звуки. Я ничего не слышу.'
        ],
        clear: [
            'Сегодня тихо. Слишком тихо.',
            'Ясное небо. Звёзды такие яркие.',
            'Без ветра. Даже листья не шевелятся.',
            'В ясную ночь видно всё. И это пугает.'
        ]
    },
    
    weatherIcons: {
        clear: '☀️',
        rain: '🌧️',
        storm: '⛈️',
        fog: '🌫️',
        snow: '❄️'
    },
    
    weatherLabels: {
        clear: 'Ясно',
        rain: 'Дождь',
        storm: 'Гроза',
        fog: 'Туман',
        snow: 'Снег'
    },
    
    start: function() {
        if (this._started) return;
        this._started = true;
        this.randomize();
        this.apply();
        if (this.interval) clearInterval(this.interval);
        this.interval = setInterval(function() {
            WeatherSystem.tick();
        }, 30000);
    },
    
    randomize: function() {
        var month = GameTime.month;
        var roll = Math.random() * 100;
        var type = 'clear';
        var intensity = 0;
        
        if (month >= 11 || month <= 2) {
            if (roll < 35) { type = 'snow'; intensity = 30 + Math.random() * 50; }
            else if (roll < 50) { type = 'fog'; intensity = 40 + Math.random() * 40; }
            else if (roll < 60) { type = 'rain'; intensity = 20 + Math.random() * 30; }
            else { type = 'clear'; intensity = 0; }
        } else if (month >= 3 && month <= 5) {
            if (roll < 40) { type = 'rain'; intensity = 30 + Math.random() * 50; }
            else if (roll < 55) { type = 'fog'; intensity = 30 + Math.random() * 30; }
            else if (roll < 65) { type = 'storm'; intensity = 50 + Math.random() * 40; }
            else { type = 'clear'; intensity = 0; }
        } else if (month >= 6 && month <= 8) {
            if (roll < 20) { type = 'storm'; intensity = 60 + Math.random() * 40; }
            else if (roll < 30) { type = 'rain'; intensity = 20 + Math.random() * 30; }
            else if (roll < 35) { type = 'fog'; intensity = 10 + Math.random() * 20; }
            else { type = 'clear'; intensity = 0; }
        } else {
            if (roll < 45) { type = 'rain'; intensity = 40 + Math.random() * 50; }
            else if (roll < 60) { type = 'fog'; intensity = 50 + Math.random() * 40; }
            else if (roll < 70) { type = 'storm'; intensity = 40 + Math.random() * 40; }
            else { type = 'clear'; intensity = 0; }
        }
        
        if (GameTime.dayPeriod === 'night' && type === 'clear' && Math.random() > 0.6) {
            var nightWeathers = ['fog', 'rain', 'storm'];
            type = nightWeathers[Math.floor(Math.random() * nightWeathers.length)];
            intensity = 30 + Math.random() * 40;
        }
        
        this.setWeather(type, intensity);
    },
    
    setWeather: function(type, intensity) {
        if (this.types.indexOf(type) === -1) type = 'clear';
        this.current = type;
        this.intensity = Math.min(100, Math.max(0, intensity || 0));
        this.nextChange = Date.now() + (5 + Math.random() * 15) * 60000;
        this.apply();
        this.updateIcons();
    },
    
    changeWeather: function(force) {
        var type;
        if (force && this.types.indexOf(force) !== -1) {
            type = force;
        } else {
            var others = [];
            for (var i = 0; i < this.types.length; i++) {
                if (this.types[i] !== this.current) {
                    others.push(this.types[i]);
                }
            }
            type = others[Math.floor(Math.random() * others.length)];
        }
        this.setWeather(type, this.intensity);
        // БАГ #4 ИСПРАВЛЕН: fallback для перевода
        showToast('🌤 ' + t('weather_changed') + ' ' + this.getWeatherLabel(type), t('system'));
    },
    
    apply: function() {
        this.clearEffects();
        
        var rainOverlay = document.getElementById('weatherRain');
        var stormFlash = document.getElementById('weatherStorm');
        var fogOverlay = document.getElementById('weatherFog');
        var snowOverlay = document.getElementById('weatherSnow');
        var condensation = document.getElementById('weatherCondensation');
        
        switch (this.current) {
            case 'rain':
                if (rainOverlay) {
                    rainOverlay.classList.add('active');
                    rainOverlay.innerHTML = '';
                    var dropCount = Math.floor(this.intensity * 1.5);
                    for (var i = 0; i < dropCount; i++) {
                        var drop = document.createElement('div');
                        drop.className = 'raindrop';
                        drop.style.left = Math.random() * 100 + '%';
                        drop.style.animationDuration = (0.5 + Math.random() * 0.8) + 's';
                        drop.style.animationDelay = Math.random() * 2 + 's';
                        drop.style.height = (10 + Math.random() * 25) + 'px';
                        drop.style.opacity = (0.2 + Math.random() * 0.4);
                        rainOverlay.appendChild(drop);
                    }
                }
                if (this.intensity > 30 && condensation) {
                    condensation.classList.add('active');
                }
                if (fogOverlay) fogOverlay.classList.remove('active');
                if (snowOverlay) snowOverlay.classList.remove('active');
                if (stormFlash) stormFlash.classList.remove('active');
                break;
                
            case 'storm':
                if (rainOverlay) {
                    rainOverlay.classList.add('active');
                    rainOverlay.innerHTML = '';
                    var dropCount2 = Math.floor(this.intensity * 1.8);
                    for (var j = 0; j < dropCount2; j++) {
                        var drop2 = document.createElement('div');
                        drop2.className = 'raindrop';
                        drop2.style.left = Math.random() * 100 + '%';
                        drop2.style.animationDuration = (0.3 + Math.random() * 0.6) + 's';
                        drop2.style.animationDelay = Math.random() * 2 + 's';
                        drop2.style.height = (15 + Math.random() * 30) + 'px';
                        drop2.style.opacity = (0.3 + Math.random() * 0.5);
                        rainOverlay.appendChild(drop2);
                    }
                }
                this.startStorm();
                if (condensation) condensation.classList.add('active');
                if (fogOverlay) fogOverlay.classList.remove('active');
                if (snowOverlay) snowOverlay.classList.remove('active');
                break;
                
            case 'fog':
                if (fogOverlay) fogOverlay.classList.add('active');
                if (condensation) condensation.classList.add('active');
                if (rainOverlay) rainOverlay.classList.remove('active');
                if (snowOverlay) snowOverlay.classList.remove('active');
                if (stormFlash) stormFlash.classList.remove('active');
                break;
                
            case 'snow':
                if (snowOverlay) {
                    snowOverlay.classList.add('active');
                    snowOverlay.innerHTML = '';
                    var flakeCount = Math.floor(this.intensity * 1.2);
                    for (var k = 0; k < flakeCount; k++) {
                        var flake = document.createElement('div');
                        flake.className = 'snowflake';
                        flake.style.left = Math.random() * 100 + '%';
                        var size = 2 + Math.random() * 4;
                        flake.style.width = size + 'px';
                        flake.style.height = size + 'px';
                        flake.style.animationDuration = (3 + Math.random() * 6) + 's';
                        flake.style.animationDelay = Math.random() * 5 + 's';
                        flake.style.opacity = (0.4 + Math.random() * 0.6);
                        snowOverlay.appendChild(flake);
                    }
                }
                if (this.intensity > 20 && condensation) {
                    condensation.classList.add('active');
                }
                if (rainOverlay) rainOverlay.classList.remove('active');
                if (fogOverlay) fogOverlay.classList.remove('active');
                if (stormFlash) stormFlash.classList.remove('active');
                break;
                
            case 'clear':
                if (rainOverlay) rainOverlay.classList.remove('active');
                if (fogOverlay) fogOverlay.classList.remove('active');
                if (snowOverlay) snowOverlay.classList.remove('active');
                if (stormFlash) stormFlash.classList.remove('active');
                if (condensation) condensation.classList.remove('active');
                break;
        }
    },
    
    clearEffects: function() {
        var rainOverlay = document.getElementById('weatherRain');
        var stormFlash = document.getElementById('weatherStorm');
        var fogOverlay = document.getElementById('weatherFog');
        var snowOverlay = document.getElementById('weatherSnow');
        var condensation = document.getElementById('weatherCondensation');
        
        if (rainOverlay) {
            rainOverlay.classList.remove('active');
            rainOverlay.innerHTML = '';
        }
        if (stormFlash) stormFlash.classList.remove('active');
        if (fogOverlay) fogOverlay.classList.remove('active');
        if (snowOverlay) {
            snowOverlay.classList.remove('active');
            snowOverlay.innerHTML = '';
        }
        if (condensation) condensation.classList.remove('active');
        
        if (this.stormInterval) {
            clearInterval(this.stormInterval);
            this.stormInterval = null;
        }
    },
    
    startStorm: function() {
        if (this.stormInterval) {
            clearInterval(this.stormInterval);
        }
        var self = this;
        this.stormInterval = setInterval(function() {
            if (Math.random() < self.intensity / 100 * 0.3) {
                var stormFlash = document.getElementById('weatherStorm');
                if (stormFlash) {
                    stormFlash.classList.add('active');
                    setTimeout(function() {
                        stormFlash.classList.remove('active');
                    }, 100 + Math.random() * 200);
                }
            }
        }, 2000 + Math.random() * 5000);
    },
    
    updateIcons: function() {
        var icon = this.weatherIcons[this.current] || '🌤️';
        var elements = document.querySelectorAll('.weather-icon, #weatherIcon, #weatherIconHome, #weatherIconMsg');
        for (var i = 0; i < elements.length; i++) {
            var el = elements[i];
            if (el) {
                el.textContent = icon;
                el.style.display = 'inline';
            }
        }
    },
    
    // БАГ #1 ИСПРАВЛЕН: добавлена функция getWeatherLabel
    getWeatherLabel: function(type) {
        var key = 'weather_' + type;
        if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
        return this.weatherLabels[type] || type;
    },
    
    getWeatherMessage: function() {
        var pool = this.weatherMessages[this.current] || this.weatherMessages.clear;
        var idx = Math.floor(Math.random() * pool.length);
        var key = 'weather_msg_' + this.current + '_' + idx;
        if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
        return pool[idx];
    },
    
    forceWeather: function(type, intensity, durationSeconds) {
        this.setWeather(type, intensity);
        this.nextChange = Date.now() + (durationSeconds || 60) * 1000;
    },
    
    tick: function() {
        if (Date.now() > this.nextChange) {
            this.randomize();
        }
    },
    
    stop: function() {
        if (this.interval) {
            clearInterval(this.interval);
            this.interval = null;
        }
        if (this.stormInterval) {
            clearInterval(this.stormInterval);
            this.stormInterval = null;
        }
    }
};

