// 6. СИСТЕМА РЕПУТАЦИИ
// ═══════════════════════════════════════════════════════════════

var ReputationSystem = {
    stars: 0,
    maxStars: 5,
    starThresholds: [0, 100, 250, 500, 1000, 2000],
    totalXP: 0,
    
    xpValues: {
        message_sent: 2,
        message_received: 1,
        clue_found: 25,
        ending_unlocked: 100,
        achievement: 50,
        call_answered: 20,
        hack_success: 75,
        katya_helped: 30,
        diary_read: 10,
        secret_found: 150,
        all_clues: 200,
        all_endings: 500,
        photo_unlocked: 5,
        act_completed: 50,
        trust_milestone: 30
    },
    
    addXP: function(action, amount) {
        var baseXP = this.xpValues[action] || 0;
        var xp = amount || baseXP;
        this.totalXP += xp;
        this.checkStars();
        this.save();
        if (xp > 5) {
            showToast('+' + xp + ' XP (' + action + ')', t('system'));
        }
        return xp;
    },
    
    checkStars: function() {
        var newStars = 0;
        for (var i = this.starThresholds.length - 1; i >= 0; i--) {
            if (this.totalXP >= this.starThresholds[i]) {
                newStars = i;
                break;
            }
        }
        if (newStars > this.stars) {
            this.stars = newStars;
            // БАГ #5 ИСПРАВЛЕН: fallback для перевода
            showToast('⭐ ' + (t('rep_up') || 'Репутация повышена! Уровень ' + this.stars), t('system'));
            if (typeof AchievementSystem !== 'undefined') {
                AchievementSystem.check('rep_level_' + this.stars);
            }
        }
        this.updateUI();
    },
    
    getStarsHTML: function() {
        var html = '<div class="reputation-stars">';
        for (var i = 1; i <= this.maxStars; i++) {
            html += '<span class="rep-star' + (i <= this.stars ? ' earned' : '') + '">⭐</span>';
        }
        return html + '</div>';
    },
    
    updateUI: function() {
        var el = document.getElementById('repDisplay');
        if (el) {
            // БАГ #5 ИСПРАВЛЕН: fallback для перевода
            el.textContent = '⭐ ' + (t('level') || 'Уровень') + ' ' + this.stars + ' (' + this.totalXP + ' XP)';
        }
        var stars = document.querySelectorAll('.rep-star');
        for (var i = 0; i < stars.length; i++) {
            stars[i].classList.toggle('earned', i < this.stars);
        }
    },
    
    getProgressToNext: function() {
        var current = this.starThresholds[this.stars];
        var next = this.starThresholds[this.stars + 1];
        if (!next) return 100;
        var progress = ((this.totalXP - current) / (next - current)) * 100;
        return Math.min(100, Math.max(0, progress));
    },
    
    save: function() {
        try {
            localStorage.setItem('nez_reputation', JSON.stringify({
                stars: this.stars,
                totalXP: this.totalXP
            }));
        } catch(e) {}
    },
    
    load: function() {
        var saved = localStorage.getItem('nez_reputation');
        if (saved) {
            try {
                var data = JSON.parse(saved);
                this.stars = data.stars || 0;
                this.totalXP = data.totalXP || 0;
            } catch(e) {}
        }
    }
};

