// 17. ГОЛОСОВЫЕ СООБЩЕНИЯ
// ═══════════════════════════════════════════════════════════════

var VoiceMessages = {
    active: null,
    playing: false,
    interval: null,
    
    toggle: function(el, duration) {
        if (!el) return;
        
        if (this.playing && this.active === el) {
            this.stop();
            return;
        }
        
        this.stop();
        this.active = el;
        this.playing = true;
        
        var btn = el.querySelector('.voice-btn');
        var waveform = el.querySelector('.voice-waveform');
        
        if (btn) {
            btn.textContent = '⏸';
            btn.classList.add('playing');
        }
        if (waveform) {
            waveform.classList.add('playing');
        }
        
        var progress = 0;
        var totalSteps = duration * 10;
        var self = this;
        this.interval = setInterval(function() {
            progress++;
            if (progress >= totalSteps) {
                self.stop();
            }
        }, 100);
    },
    
    stop: function() {
        if (this.active) {
            var btn = this.active.querySelector('.voice-btn');
            var waveform = this.active.querySelector('.voice-waveform');
            
            if (btn) {
                btn.textContent = '▶';
                btn.classList.remove('playing');
            }
            if (waveform) {
                waveform.classList.remove('playing');
            }
        }
        
        this.playing = false;
        this.active = null;
        
        if (this.interval) {
            clearInterval(this.interval);
            this.interval = null;
        }
    }
};

