// 18. СИСТЕМА ВЫБОРОВ
// ═══════════════════════════════════════════════════════════════

function showChoices(list) {
    var area = document.getElementById('choicesArea');
    if (!area) return;
    
    area.className = 'choices-area show';
    
    var oldButtons = area.querySelectorAll('.choice-btn');
    for (var i = 0; i < oldButtons.length; i++) {
        oldButtons[i].remove();
    }
    
    for (var j = 0; j < list.length; j++) {
        var choice = list[j];
        var choiceTxt = choice.txt;
        if (choice.id && I18N[currentLang] && I18N[currentLang][choice.id]) {
            choiceTxt = t(choice.id);
        } else if (choice.id && I18N.ru && I18N.ru[choice.id] === undefined) {
            I18N.ru[choice.id] = choice.txt;
        }
        var btn = document.createElement('button');
        btn.className = 'choice-btn' + (choice.dng ? ' danger' : '');
        btn.textContent = choiceTxt;
        
        btn.onclick = function(c, txt) {
            return function() {
                area.className = 'choices-area';
                G.choices.push(c.id);
                GameTime.advance(1 + Math.floor(Math.random() * 3));
                addMessage('out', txt);
                if (c.p) adj(c.p);
                if (typeof AchievementSystem !== 'undefined') {
                    AchievementSystem.checkAll();
                }
                setTimeout(function() {
                    if (c.next) c.next();
                }, 800);
            };
        }(choice, choiceTxt);
        
        area.appendChild(btn);
    }
    
    scrollChatDown();
}

