function buildHomeGrid() {
    var grid = document.getElementById('homeGrid');
    if (!grid) return;
    
    var allApps = [
        { id: 'msg', icon: '💬', label: 'Zapregram', gradient: 'linear-gradient(140deg,#0e1c3a,#152a5c)', always: true },
        { id: 'gallery', icon: '🖼️', label: AppStore.getField('gallery', 'name'), gradient: 'linear-gradient(140deg,#2a0e32,#1c0822)', always: false },
        { id: 'browser', icon: '🌐', label: AppStore.getField('browser', 'name'), gradient: 'linear-gradient(140deg,#0e2a1c,#0a1c12)', always: false },
        { id: 'contacts', icon: '👥', label: AppStore.getField('contacts', 'name'), gradient: 'linear-gradient(140deg,#2a1c0e,#1c1208)', always: false },
        { id: 'notes', icon: '📝', label: AppStore.getField('notes', 'name'), gradient: 'linear-gradient(140deg,#1e2a0e,#141e0a)', always: false },
        { id: 'settings', icon: '⚙️', label: AppStore.getField('settings', 'name'), gradient: 'linear-gradient(140deg,#1e1e26,#12121c)', always: true },
        { id: 'authors', icon: '⭐', label: AppStore.getField('authors', 'name'), gradient: 'linear-gradient(140deg,#1a1040,#100a28)', always: true },
        { id: 'support', icon: '💜', label: AppStore.getField('support', 'name'), gradient: 'linear-gradient(140deg,#300e28,#1e0a1a)', always: true },
        { id: 'appstore', icon: '🏪', label: t('app_store_short') || 'Магазин', gradient: 'linear-gradient(140deg,#1a1a2e,#2a2a4e)', always: true }
    ];
    
    var html = '';
    var readyCount = (typeof AppStore !== 'undefined') ? AppStore.getReadyToInstallApps().length : 0;
    
    for (var i = 0; i < allApps.length; i++) {
        var app = allApps[i];
        if (!app.always && !(typeof AppStore !== 'undefined' && AppStore.isUnlocked(app.id))) continue; // плавный онбординг: скрываем до разблокировки
        var action = app.id === 'support' ? 'openDonat()' : "openApp('" + app.id + "')";
        html += '<div class="aicon" onclick="' + action + '">' +
            '<div class="abox" style="background:' + app.gradient + ';">' +
                '<span style="font-size:26px;position:relative;z-index:1;">' + app.icon + '</span>' +
                (app.id === 'msg' ? '<span class="abadge show" id="msgBadge">1</span>' : '') +
                (app.id === 'appstore' && readyCount > 0 ? '<span class="abadge show" style="background:var(--violet);">' + readyCount + '</span>' : '') +
            '</div>' +
            '<div class="alabel">' + app.label + '</div>' +
        '</div>';
    }
    
    var unlockableApps = [
        { id: 'camera', icon: '📸', label: t('home_label_camera') },
        { id: 'dictaphone', icon: '🎙️', label: t('home_label_dictaphone') },
        { id: 'map', icon: '🗺️', label: t('home_label_map') },
        { id: 'calculator', icon: '🔢', label: t('home_label_calculator') },
        { id: 'investigation', icon: '🔍', label: t('home_label_investigation') },
        { id: 'diary', icon: '📔', label: t('home_label_diary') },
        { id: 'endings', icon: '🏆', label: t('home_label_endings') }
    ];
    
    var gradients = {
        camera: 'linear-gradient(140deg,#2a1a0e,#1e1008)',
        dictaphone: 'linear-gradient(140deg,#1e1040,#2a1560)',
        map: 'linear-gradient(140deg,#0a1a2e,#0a1c12)',
        calculator: 'linear-gradient(140deg,#2a1c0e,#1c1208)',
        investigation: 'linear-gradient(140deg,#1a1030,#2a1850)',
        diary: 'linear-gradient(140deg,#301a20,#1a0e14)',
        endings: 'linear-gradient(140deg,#1a3010,#0e1a08)'
    };
    
    for (var j = 0; j < unlockableApps.length; j++) {
        var app = unlockableApps[j];
        if (AppStore.isUnlocked(app.id)) {
            html += '<div class="aicon" onclick="openApp(\'' + app.id + '\')">' +
                '<div class="abox" style="background:' + (gradients[app.id] || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)') + ';">' +
                    '<span style="font-size:26px;position:relative;z-index:1;">' + app.icon + '</span>' +
                '</div>' +
                '<div class="alabel">' + app.label + '</div>' +
            '</div>';
        }
    }
    
    grid.innerHTML = html;
}

