// 24. СИСТЕМА ЗВОНКОВ (ПОЛНАЯ)
// ═══════════════════════════════════════════════════════════════

var CallSystem = {
    active: false,
    caller: null,
    callStartTime: 0,
    callInterval: null,
    transcriptLines: [],
    isIncoming: false,
    _autoAnswerTimeout: null,

    incomingCall: function(caller) {
        if (this.active || this.isIncoming) return;
        this.caller = caller;
        this.isIncoming = true;

        var screen = document.getElementById('callScreen');
        var avatar = document.getElementById('callAvatar');
        var name = document.getElementById('callName');
        var status = document.getElementById('callStatus');
        var duration = document.getElementById('callDuration');
        var actions = document.getElementById('callActions');
        var transcript = document.getElementById('callTranscript');

        if (!screen || !avatar || !name || !status) return;

        screen.classList.add('active');
        avatar.textContent = caller.avatar || '📞';
        name.textContent = caller.name || t('incoming_call');
        status.textContent = t('call_status_incoming');
        if (duration) duration.style.display = 'none';
        if (actions) actions.style.display = 'flex';
        if (transcript) {
            transcript.style.display = 'none';
            transcript.innerHTML = '';
        }
        this.transcriptLines = [];

        // БАГ #13 ИСПРАВЛЕН: проверка на vibrate уже есть
        if (navigator.vibrate) {
            navigator.vibrate([200, 100, 200, 100, 200]);
        }

        var self = this;
        this._autoAnswerTimeout = setTimeout(function() {
            if (self.isIncoming && self.caller) {
                self.accept();
            }
        }, 10000);
    },

    accept: function() {
        if (!this.caller || !this.isIncoming) return;
        this.isIncoming = false;
        this.active = true;
        this.callStartTime = Date.now();

        if (this._autoAnswerTimeout) {
            clearTimeout(this._autoAnswerTimeout);
            this._autoAnswerTimeout = null;
        }

        var status = document.getElementById('callStatus');
        var duration = document.getElementById('callDuration');
        var actions = document.getElementById('callActions');
        var transcript = document.getElementById('callTranscript');

        if (status) status.textContent = t('call_status_connecting');
        if (actions) actions.style.display = 'none';

        if (navigator.vibrate) {
            navigator.vibrate(0);
        }

        var self = this;
        setTimeout(function() {
            if (status) status.textContent = t('call_status_talking');
            if (duration) duration.style.display = 'block';
            if (transcript) {
                transcript.style.display = 'block';
                transcript.innerHTML = '';
            }
            self.updateCallDuration();
            self.callInterval = setInterval(function() {
                self.updateCallDuration();
            }, 1000);
            
            ReputationSystem.addXP('call_answered');
            
            if (self.caller && self.caller.script) {
                self.caller.script();
            }
        }, 1500);
    },

    decline: function() {
        if (this._autoAnswerTimeout) {
            clearTimeout(this._autoAnswerTimeout);
            this._autoAnswerTimeout = null;
        }

        var screen = document.getElementById('callScreen');
        if (screen) screen.classList.remove('active');
        this.active = false;
        this.isIncoming = false;

        if (this.callInterval) {
            clearInterval(this.callInterval);
            this.callInterval = null;
        }

        var transcript = document.getElementById('callTranscript');
        if (transcript) transcript.style.display = 'none';

        if (navigator.vibrate) {
            navigator.vibrate(0);
        }

        showToast(t('missed_call'), t('phone_app'));

        if (this.caller && this.caller.onMissed) {
            var callerRef = this.caller;
            setTimeout(function() {
                callerRef.onMissed();
            }, 2000);
        }
        this.caller = null;
    },

    endCall: function() {
        var status = document.getElementById('callStatus');
        if (status) status.textContent = t('call_status_ended');
        
        if (this.callInterval) {
            clearInterval(this.callInterval);
            this.callInterval = null;
        }

        if (navigator.vibrate) {
            navigator.vibrate(0);
        }

        var self = this;
        setTimeout(function() {
            var screen = document.getElementById('callScreen');
            if (screen) screen.classList.remove('active');
            self.active = false;
            self.isIncoming = false;

            var transcript = document.getElementById('callTranscript');
            if (transcript) {
                transcript.style.display = 'none';
                transcript.innerHTML = '';
            }

            self.caller = null;
        }, 1500);
    },

    updateCallDuration: function() {
        var elapsed = Math.floor((Date.now() - this.callStartTime) / 1000);
        var mins = Math.floor(elapsed / 60);
        var secs = elapsed % 60;
        var duration = document.getElementById('callDuration');
        if (duration) {
            duration.textContent = String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
        }
    },

    addTranscriptLine: function(speaker, text) {
        var transcript = document.getElementById('callTranscript');
        if (!transcript) return;

        var line = document.createElement('div');
        line.className = 'call-transcript-line ' + speaker;
        line.textContent = (speaker === 'you' ? t('call_you') : t('call_interlocutor')) + text;
        transcript.appendChild(line);
        transcript.scrollTop = transcript.scrollHeight;
        this.transcriptLines.push({ speaker: speaker, text: text });
    },

    init: function() {
        var callScreen = document.getElementById('callScreen');
        var callTranscript = document.getElementById('callTranscript');
        var callDuration = document.getElementById('callDuration');
        var callActions = document.getElementById('callActions');

        if (callScreen) callScreen.classList.remove('active');
        if (callTranscript) callTranscript.style.display = 'none';
        if (callDuration) callDuration.style.display = 'none';
        if (callActions) callActions.style.display = 'flex';

        var acceptBtn = document.getElementById('callAcceptBtn');
        var declineBtn = document.getElementById('callDeclineBtn');
        var self = this;

        if (acceptBtn && !acceptBtn._callBound) {
            acceptBtn._callBound = true;
            acceptBtn.addEventListener('click', function() {
                self.accept();
            });
        }

        if (declineBtn && !declineBtn._callBound) {
            declineBtn._callBound = true;
            declineBtn.addEventListener('click', function() {
                self.decline();
            });
        }
    }
};

