// 25. СИСТЕМА ФЛЕШБЕКОВ
// ═══════════════════════════════════════════════════════════════

var FlashbackSystem = {
    overlay: null,
    content: null,
    onComplete: null,
    isActive: false,

    show: function(date, text, callback) {
        this.overlay = document.getElementById('flashbackOverlay');
        this.content = document.getElementById('flashbackContent');
        if (!this.overlay || !this.content) return;

        this.content.innerHTML = 
            '<div class="flashback-date">' + date + '</div>' +
            '<div class="flashback-text">' + text + '</div>' +
            '<div class="flashback-continue">' + (t('click_to_continue') || 'нажмите чтобы продолжить') + '</div>';

        this.overlay.classList.add('active');
        this.isActive = true;
        this.onComplete = callback;

        var self = this;
        var closeHandler = function(e) {
            if (e.target === self.overlay || e.target.classList.contains('flashback-vignette') || 
                e.target.classList.contains('flashback-continue') || e.target.closest('.flashback-content')) {
                self.hide();
                self.overlay.removeEventListener('click', closeHandler);
            }
        };
        this.overlay.addEventListener('click', closeHandler);
    },

    hide: function() {
        if (this.overlay) {
            this.overlay.classList.remove('active');
        }
        this.isActive = false;
        if (this.onComplete) {
            var cb = this.onComplete;
            setTimeout(function() {
                cb();
            }, 500);
            this.onComplete = null;
        }
    },

    init: function() {
        var overlay = document.getElementById('flashbackOverlay');
        if (overlay && !overlay._flashbackBound) {
            overlay._flashbackBound = true;
            var self = this;
            overlay.addEventListener('click', function(e) {
                if (e.target === overlay || e.target.classList.contains('flashback-vignette')) {
                    self.hide();
                }
            });
        }
    }
};

// ═══════════════════════════════════════════════════════════════
// 26. МИНИ-ИГРА "ВЗЛОМ" (ПОЛНАЯ)
// ═══════════════════════════════════════════════════════════════

var HackGame = {
    active: false,
    targetPassword: '',
    attempts: 0,
    maxAttempts: 5,
    onSuccess: null,
    onFail: null,
    isLocked: false,

    start: function(targetPassword, clues, callback, failCallback) {
        this.active = true;
        this.targetPassword = targetPassword;
        this.attempts = 0;
        this.isLocked = false;
        this.onSuccess = callback;
        this.onFail = failCallback || null;

        var screen = document.getElementById('hackScreen');
        if (!screen) return;
        screen.classList.add('active');

        var attemptsEl = document.getElementById('hackAttempts');
        if (attemptsEl) {
            attemptsEl.textContent = t('hack_attempts_label') + this.maxAttempts;
        }

        for (var i = 0; i < 4; i++) {
            var dot = document.getElementById('dot' + i);
            if (dot) dot.className = 'hack-dot';
        }

        var terminal = document.getElementById('hackTerminal');
        if (terminal) terminal.innerHTML = '';

        var input = document.getElementById('hackInput');
        if (input) {
            input.value = '';
            input.disabled = false;
            setTimeout(function() {
                input.focus();
            }, 500);
        }

        var self = this;
        setTimeout(function() {
            self.addTerminalLine(t('hack_init'), 'info');
        }, 300);
        
        setTimeout(function() {
            self.addTerminalLine(t('hack_connecting'), 'info');
        }, 600);
        
        setTimeout(function() {
            self.addTerminalLine(t('hack_bypassing'), 'info');
        }, 900);
        
        setTimeout(function() {
            self.addTerminalLine(t('hack_established'), 'success');
        }, 1200);
        
        setTimeout(function() {
            self.addTerminalLine(t('hack_enter_password'), 'warning');
        }, 1500);

        if (clues && clues.length > 0) {
            setTimeout(function() {
                self.addTerminalLine(t('hack_found_clues_header'), 'info');
                for (var j = 0; j < clues.length; j++) {
                    self.addTerminalLine('• ' + clues[j], 'info');
                }
            }, 1800);
        }
    },

    addTerminalLine: function(text, type) {
        var terminal = document.getElementById('hackTerminal');
        if (!terminal) return;

        var line = document.createElement('div');
        line.className = 'hack-line ' + (type || '');
        var prefix = type ? '[' + type.toUpperCase() + '] ' : '';
        line.textContent = prefix + text;
        terminal.appendChild(line);
        terminal.scrollTop = terminal.scrollHeight;
    },

    tryPassword: function(input) {
        if (!this.active || this.isLocked) return;
        if (this.attempts >= this.maxAttempts) return;

        this.attempts++;
        var remaining = this.maxAttempts - this.attempts;

        var attemptsEl = document.getElementById('hackAttempts');
        if (attemptsEl) {
            attemptsEl.textContent = t('hack_attempts_label') + remaining;
        }

        for (var i = 0; i < 4; i++) {
            var dot = document.getElementById('dot' + i);
            if (dot) {
                if (i < input.length) {
                    dot.classList.add('filled');
                } else {
                    dot.classList.remove('filled');
                }
            }
        }

        if (input === this.targetPassword) {
            this.addTerminalLine(t('hack_password_accepted'), 'success');
            this.addTerminalLine(t('hack_access_granted'), 'success');
            AchievementSystem.unlock('hack_complete');
            ReputationSystem.addXP('hack_success');
            G.hackCompleted = true;

            var self = this;
            setTimeout(function() {
                self.addTerminalLine(t('hack_files_downloaded'), 'success');
                self.addTerminalLine(t('hack_disconnected'), 'warning');
                setTimeout(function() {
                    var screen = document.getElementById('hackScreen');
                    if (screen) screen.classList.remove('active');
                    self.active = false;
                    if (self.onSuccess) self.onSuccess();
                }, 1500);
            }, 2000);
        } else {
            this.addTerminalLine(t('hack_wrong_password'), 'error');

            for (var j = 0; j < 4; j++) {
                var dotEl = document.getElementById('dot' + j);
                if (dotEl) {
                    dotEl.classList.add('wrong');
                    (function(dot) {
                        setTimeout(function() {
                            dot.classList.remove('wrong');
                        }, 500);
                    })(dotEl);
                }
            }

            var self = this;

            if (remaining === 3) {
                setTimeout(function() {
                    self.addTerminalLine(t('hack_hint_1'), 'warning');
                }, 800);
            } else if (remaining === 2) {
                setTimeout(function() {
                    self.addTerminalLine(t('hack_hint_2'), 'warning');
                }, 800);
            } else if (remaining === 1) {
                setTimeout(function() {
                    self.addTerminalLine(t('hack_last_attempt'), 'warning');
                    self.addTerminalLine(t('hack_hint_3'), 'warning');
                }, 800);
            } else if (remaining <= 0) {
                this.isLocked = true;
                this.addTerminalLine(t('hack_locked'), 'error');
                this.addTerminalLine(t('hack_disconnected'), 'error');
                
                var hackInput = document.getElementById('hackInput');
                if (hackInput) hackInput.disabled = true;
                
                setTimeout(function() {
                    var screen = document.getElementById('hackScreen');
                    if (screen) screen.classList.remove('active');
                    self.active = false;
                    if (self.onFail) self.onFail();
                }, 2000);
            }
        }
    },

    quit: function() {
        if (!this.active) return;
        this.addTerminalLine(t('hack_disconnected_by_user'), 'warning');
        var self = this;
        setTimeout(function() {
            var screen = document.getElementById('hackScreen');
            if (screen) screen.classList.remove('active');
            self.active = false;
        }, 500);
    },

    init: function() {
        var hackInput = document.getElementById('hackInput');
        if (hackInput && !hackInput._hackBound) {
            hackInput._hackBound = true;
            var self = this;
            hackInput.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' && self.active) {
                    self.tryPassword(hackInput.value);
                    hackInput.value = '';
                }
                if (!/^[0-9]$/.test(e.key) && e.key !== 'Backspace' && e.key !== 'Delete' && e.key !== 'Enter') {
                    e.preventDefault();
                }
            });
            
            hackInput.addEventListener('input', function() {
                if (this.value.length > 4) {
                    this.value = this.value.slice(0, 4);
                }
            });
        }
    }
};

// ═══════════════════════════════════════════════════════════════
// 27. ПАСХАЛКИ (ПОЛНЫЕ) — ИСПРАВЛЕНЫ
// ═══════════════════════════════════════════════════════════════

var EasterEggs = {
    konamiSequence: ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'],
    konamiProgress: 0,
    secretButtonClicks: 0,
    secretDotAdded: false,
    ghostMessageTriggered: false,

    init: function() {
        this.addKonamiListener();
        this.addSecretButton();
        this.scheduleRandomEgg();
    },

    addKonamiListener: function() {
        var self = this;
        document.addEventListener('keydown', function(e) {
            var key = e.key;
            if (key === self.konamiSequence[self.konamiProgress]) {
                self.konamiProgress++;
                if (self.konamiProgress >= 5) {
                    var hint = document.getElementById('konamiHint');
                    if (hint) {
                        hint.classList.add('visible');
                        setTimeout(function() {
                            hint.classList.remove('visible');
                        }, 2000);
                    }
                }
                if (self.konamiProgress >= self.konamiSequence.length) {
                    self.activateKonami();
                    self.konamiProgress = 0;
                }
            } else {
                self.konamiProgress = 0;
            }
        });
    },

    activateKonami: function() {
        AchievementSystem.unlock('konami');
        // БАГ #14 ИСПРАВЛЕН: используем только существующие фото
        var allGalleryIds = ['g0', 'g1', 'g2', 'g3', 'g4', 'g5', 'g6', 'g7', 'g8', 'g9', 'g10', 'g11', 'g12', 'g13', 'g14', 'g15', 'g16', 'g17', 'g18', 'g19'];
        for (var i = 0; i < allGalleryIds.length; i++) {
            if (G.galleryUnlocked.indexOf(allGalleryIds[i]) === -1) {
                G.galleryUnlocked.push(allGalleryIds[i]);
            }
        }
        for (var j = 0; j < ClueSystem.clues.length; j++) {
            ClueSystem.clues[j].found = true;
        }
        P.trust = 100;
        P.courage = 100;
        
        var screen = document.getElementById('screen');
        if (screen) {
            screen.classList.add('easter-egg-found');
            setTimeout(function() {
                screen.classList.remove('easter-egg-found');
            }, 1500);
        }
        
        showToast('🎮 ' + t('egg_konami_activated'), t('egg_label'));
        ReputationSystem.addXP('secret_found', 200);
        
        if (G.gameStarted) {
            setTimeout(function() {
                addChatSystem('🐛 ' + t('egg_konami_dev_credit'));
                addMessage('in', t('egg_konami_msg'), { id: 'konami_egg' });
            }, 2000);
        }
    },

    addSecretButton: function() {
        var settingsView = document.getElementById('settings');
        if (!settingsView) return;
        
        var self = this;
        var observer = new MutationObserver(function() {
            if (settingsView.classList.contains('active')) {
                if (!self.secretDotAdded) {
                    self.createSecretDot();
                }
            } else {
                self.removeSecretDot();
            }
        });
        observer.observe(settingsView, {
            attributes: true,
            attributeFilter: ['class']
        });
    },

    createSecretDot: function() {
        var settingsBody = document.getElementById('settingsBody');
        if (!settingsBody || this.secretDotAdded) return;
        
        var dot = document.createElement('div');
        dot.className = 'secret-dot';
        dot.id = 'secretDot';
        dot.style.cssText = 'top:8px;right:8px;position:absolute;cursor:pointer;z-index:10;width:6px;height:6px;border-radius:50%;background:rgba(255,215,0,0.6);animation:secretPulse 2s ease-in-out infinite;';
        dot.title = '???';
        
        var self = this;
        dot.onclick = function(e) {
            e.stopPropagation();
            self.secretButtonClicks++;
            
            if (self.secretButtonClicks === 1) {
                showToast(t('egg_secret_1'), '???');
            } else if (self.secretButtonClicks === 3) {
                showToast(t('egg_secret_3'), '???');
            } else if (self.secretButtonClicks === 5) {
                showToast(t('egg_secret_5'), '???');
            } else if (self.secretButtonClicks === 7) {
                showToast(t('egg_secret_7'), '???');
            } else if (self.secretButtonClicks >= 10) {
                AchievementSystem.unlock('secret_button');
                ReputationSystem.addXP('secret_found', 150);
                showToast('🔮 ' + t('egg_secret_found'), t('egg_label'));
                self.removeSecretDot();
                if (G.gameStarted) {
                    setTimeout(function() {
                        addMessage('in', t('egg_secret_btn_msg'), { id: 'secret_btn_egg' });
                    }, 3000);
                }
            }
        };
        
        settingsBody.style.position = 'relative';
        settingsBody.appendChild(dot);
        this.secretDotAdded = true;
    },

    removeSecretDot: function() {
        var dot = document.getElementById('secretDot');
        if (dot) dot.remove();
        this.secretDotAdded = false;
    },

    scheduleRandomEgg: function() {
        var self = this;
        setInterval(function() {
            if (Math.random() < 0.01 && G.gameStarted && !G.endingReached) {
                var eggs = [
                    function() {
                        showToast('🐱 ' + t('egg_cat_meow'), '???');
                        addChatSystem(t('egg_meow_sound'));
                    },
                    function() {
                        showToast('📺 ' + t('egg_screen_glitch'), '???');
                        var screen = document.getElementById('screen');
                        if (screen) {
                            screen.classList.add('glitch-fx');
                            setTimeout(function() {
                                screen.classList.remove('glitch-fx');
                            }, 500);
                        }
                    },
                    function() {
                        showToast('👁️ ' + t('egg_did_you_imagine'), '???');
                        P.paranoia += 5;
                    },
                    function() {
                        if (!self.ghostMessageTriggered) {
                            self.ghostMessageTriggered = true;
                            var msgId = addMessage('in', t('egg_ghost_msg'), { id: 'ghost_egg_' + Date.now() });
                            setTimeout(function() {
                                deleteMessage(msgId);
                                AchievementSystem.unlock('ghost_whisperer');
                            }, 3000);
                        }
                    }
                ];
                eggs[Math.floor(Math.random() * eggs.length)]();
            }
        }, 300000);
    }
};

