function getGalleryField(photo, field) {
    var key = 'gallery_' + photo.id + '_' + field;
    if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
    return photo[field];
}

function buildGallery() {
    var grid = document.getElementById('galGrid');
    if (!grid) return;
    
    var html = '';
    
    for (var i = 0; i < GALLERY_DATA.length; i++) {
        var photo = GALLERY_DATA[i];
        var isUnlocked = G.galleryUnlocked && G.galleryUnlocked.indexOf(photo.id) !== -1;
        var isSecret = photo.id === 'g5';
        var photoTitle = getGalleryField(photo, 'title');
        
        var clickAction;
        if (!isUnlocked) {
            if (isSecret) {
                clickAction = "showToast('🔒 " + (t('secret_file') || 'Секретный файл. Попробуйте калькулятор.') + "', '" + (t('gallery') || 'Галерея') + "')";
            } else {
                clickAction = "showToast('🔒 " + (t('locked') || 'Ещё не разблокировано') + "', '" + (t('gallery') || 'Галерея') + "')";
            }
        } else {
            clickAction = "openGalleryPhoto('" + photo.id + "')";
        }
        
        var imageHtml = '';
        if (isUnlocked && photo.image) {
            imageHtml = '<div style="position:relative;width:100%;height:100%;">' +
                '<img src="' + photo.image + '" style="width:100%;height:100%;object-fit:cover;border-radius:12px;" alt="' + escapeHTML(photoTitle) + '" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';">' +
                '<div style="position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:var(--surface);border-radius:12px;font-size:24px;">' + photo.icon + '</div>' +
            '</div>';
        } else {
            imageHtml = '<div class="gallery-cell-icon">' + photo.icon + '</div>' +
                '<div style="font-size:8px;color:var(--text-tertiary);">' + (isUnlocked ? escapeHTML(photoTitle) : '???') + '</div>';
        }
        
        html += '<div class="gallery-cell" onclick="' + clickAction + '">' +
            '<div class="gallery-cell-inner" style="' + (isUnlocked && photo.image ? 'padding:0;' : '') + '">' +
                imageHtml +
            '</div>' +
            (!isUnlocked ? '<div class="gallery-lock">🔒</div>' : '') +
            (isUnlocked && isSecret ? '<div style="position:absolute;top:4px;right:4px;font-size:10px;color:var(--gold);">⭐</div>' : '') +
        '</div>';
    }
    
    grid.innerHTML = html;
}

var galleryViewerIndex = -1;

function getUnlockedGalleryIndexes() {
    var result = [];
    for (var i = 0; i < GALLERY_DATA.length; i++) {
        if (G.galleryUnlocked && G.galleryUnlocked.indexOf(GALLERY_DATA[i].id) !== -1) {
            result.push(i);
        }
    }
    return result;
}

function openGalleryPhoto(photoId) {
    var idx = -1;
    for (var i = 0; i < GALLERY_DATA.length; i++) {
        if (GALLERY_DATA[i].id === photoId) {
            idx = i;
            break;
        }
    }
    if (idx === -1) return;
    
    galleryViewerIndex = idx;
    renderGalleryViewer();
    
    var viewer = document.getElementById('galleryViewer');
    if (viewer) viewer.classList.add('open');
}

function closeGalleryPhoto() {
    var viewer = document.getElementById('galleryViewer');
    if (viewer) viewer.classList.remove('open');
}

function galleryViewerNav(dir) {
    var unlockedIdx = getUnlockedGalleryIndexes();
    if (unlockedIdx.length === 0) return;
    
    var pos = unlockedIdx.indexOf(galleryViewerIndex);
    if (pos === -1) pos = 0;
    pos = (pos + dir + unlockedIdx.length) % unlockedIdx.length;
    
    galleryViewerIndex = unlockedIdx[pos];
    renderGalleryViewer();
}

function renderGalleryViewer() {
    var photo = GALLERY_DATA[galleryViewerIndex];
    if (!photo) return;
    
    var titleEl = document.getElementById('galleryViewerTitle');
    var descEl = document.getElementById('galleryViewerDesc');
    var imageEl = document.getElementById('galleryViewerImage');
    var counterEl = document.getElementById('galleryViewerCounter');
    
    var photoTitle = getGalleryField(photo, 'title');
    var photoDesc = getGalleryField(photo, 'desc');
    
    if (titleEl) titleEl.textContent = photoTitle;
    if (descEl) descEl.textContent = photoDesc;
    
    if (imageEl) {
        if (photo.image) {
            imageEl.innerHTML =
                '<img src="' + photo.image + '" alt="' + escapeHTML(photoTitle) + '" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';">' +
                '<div class="gallery-viewer-fallback">' + photo.icon + '</div>';
        } else {
            imageEl.innerHTML = '<div class="gallery-viewer-fallback" style="display:flex;">' + photo.icon + '</div>';
        }
    }
    
    if (counterEl) {
        var unlockedIdx = getUnlockedGalleryIndexes();
        var pos = unlockedIdx.indexOf(galleryViewerIndex);
        counterEl.textContent = (pos + 1) + ' / ' + unlockedIdx.length;
    }
}

