function getArticleField(article, field) {
    var key = 'article_' + article.id + '_' + field;
    if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
    return article[field];
}

var currentArticle = null;
var browserHistory = [];

function buildBrowser() {
    var content = document.getElementById('browserContent');
    if (!content) return;
    
    if (currentArticle !== null) {
        renderArticle(currentArticle);
        return;
    }
    
    var html = '';
    html += '<div class="browser-search-title">' + (t('search_label') || 'ПОИСК') + '</div>';
    html += '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);margin-bottom:16px;">' + (t('found_results') || 'Найдено') + ': ' + BROWSER_ARTICLES.length + ' ' + (t('results') || 'результатов') + '</div>';
    
    for (var i = 0; i < BROWSER_ARTICLES.length; i++) {
        var article = BROWSER_ARTICLES[i];
        html += '<div class="browser-result" onclick="openBrowserArticle(' + i + ')">' +
            '<div class="browser-result-url">' + article.url + '</div>' +
            '<div class="browser-result-title">' + escapeHTML(getArticleField(article, 'title')) + '</div>' +
            '<div class="browser-result-desc">' + escapeHTML(getArticleField(article, 'desc')) + '</div>' +
        '</div>';
    }
    
    content.innerHTML = html;
}

function openBrowserArticle(index) {
    var article = BROWSER_ARTICLES[index];
    if (!article) return;
    
    currentArticle = index;
    renderArticle(index);
}

function renderArticle(index) {
    var article = BROWSER_ARTICLES[index];
    if (!article) return;
    
    var content = document.getElementById('browserContent');
    if (!content) return;
    
    var html = '';
    html += '<div class="browser-article">';
    html += '<div class="browser-article-back" onclick="closeBrowserArticle()">‹ ' + (t('back') || 'Назад') + '</div>';
    html += '<div class="browser-article-url" style="font-family:var(--font-mono);font-size:9px;color:var(--teal);margin-bottom:8px;">' + article.url + '</div>';
    html += '<div class="browser-article-title">' + escapeHTML(getArticleField(article, 'title')) + '</div>';
    html += '<div class="browser-article-text">' + escapeHTML(getArticleField(article, 'full')).replace(/\n/g, '<br>') + '</div>';
    html += '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);margin-top:16px;border-top:1px solid var(--border-color);padding-top:12px;">' + (t('read_at') || 'Прочитано') + ': ' + new Date().toLocaleDateString() + '</div>';
    html += '</div>';
    
    content.innerHTML = html;
    browserHistory.push(index);
}

function closeBrowserArticle() {
    currentArticle = null;
    browserHistory = [];
    buildBrowser();
}

function goBackInBrowser() {
    if (browserHistory.length > 1) {
        browserHistory.pop();
        var last = browserHistory[browserHistory.length - 1];
        currentArticle = last;
        renderArticle(last);
    } else {
        closeBrowserArticle();
    }
}

