function buildContacts() {
    var list = document.getElementById('contactsList');
    var profile = document.getElementById('contactProfile');
    
    if (list) list.style.display = 'block';
    if (profile) {
        profile.style.display = 'none';
        profile.className = 'contacts-profile';
    }
    
    if (!list) return;
    
    var contacts = (typeof CONTACTS_DATA !== 'undefined') ? CONTACTS_DATA : [];
    
    if (contacts.length === 0) {
        list.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-tertiary);font-family:var(--font-mono);">' + t('no_contacts') + '</div>';
        return;
    }
    
    var html = '';
    for (var i = 0; i < contacts.length; i++) {
        var c = contacts[i];
        var escapedName = escapeHTML(getContactField(c, 'name'));
        var fullDesc = getContactField(c, 'description');
        var escapedDesc = escapeHTML(fullDesc.length > 40 ? fullDesc.substring(0, 40) + '...' : fullDesc);
        var statusDot = c.statusCode === 'online' ? '🟢' : (c.statusCode === 'recent' ? '🟡' : '⚪');
        
        html += '<div class="contact-item" onclick="openContactProfile(\'' + c.id + '\')">' +
            '<div class="contact-avatar">' + c.avatar + '</div>' +
            '<div class="contact-info-text">' +
                '<div class="contacts-name">' + escapedName + ' <span style="font-size:10px;">' + statusDot + '</span></div>' +
                '<div class="contact-detail">' + escapedDesc + '</div>' +
            '</div>' +
            '<div class="contact-chevron">›</div>' +
        '</div>';
    }
    
    list.innerHTML = html;
}

function openContactProfile(contactId) {
    var contacts = (typeof CONTACTS_DATA !== 'undefined') ? CONTACTS_DATA : [];
    var contact = null;
    
    for (var i = 0; i < contacts.length; i++) {
        if (contacts[i].id === contactId) {
            contact = contacts[i];
            break;
        }
    }
    
    if (!contact) return;
    
    var list = document.getElementById('contactsList');
    var profile = document.getElementById('contactProfile');
    
    if (list) list.style.display = 'none';
    if (!profile) return;
    
    profile.style.display = 'block';
    profile.className = 'contacts-profile show';
    
    var statusDot = contact.statusCode === 'online' ? '🟢' : (contact.statusCode === 'recent' ? '🟡' : '⚪');
    
    var tags = getContactTags(contact);
    var tagsHtml = '';
    for (var j = 0; j < tags.length; j++) {
        tagsHtml += '<span style="background:rgba(124,92,252,0.1);border:1px solid rgba(124,92,252,0.15);border-radius:12px;padding:2px 10px;font-family:var(--font-mono);font-size:8px;color:var(--violet);">' + escapeHTML(tags[j]) + '</span>';
    }
    
    profile.innerHTML = 
        '<div style="text-align:center;padding:20px;">' +
            '<div class="contact-profile-avatar">' + contact.avatar + '</div>' +
            '<h2 class="contact-profile-name">' + escapeHTML(getContactField(contact, 'name')) + ' ' + statusDot + '</h2>' +
            '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);margin-bottom:8px;">' + escapeHTML(getContactField(contact, 'relation')) + ' · ' + escapeHTML(getContactField(contact, 'mood')) + '</div>' +
            '<p class="contact-profile-desc">' + escapeHTML(getContactField(contact, 'description')) + '</p>' +
            '<div style="margin:12px 0;display:flex;flex-wrap:wrap;gap:6px;justify-content:center;">' + tagsHtml + '</div>' +
            '<div style="background:var(--depth);border-radius:12px;padding:12px;text-align:left;margin:12px 0;font-family:var(--font-mono);font-size:10.5px;color:var(--text-secondary);line-height:1.8;">' +
                '<div style="font-weight:700;color:var(--violet);margin-bottom:4px;">📖 ' + t('story') + '</div>' +
                escapeHTML(getContactField(contact, 'story')) +
            '</div>' +
            '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);margin-bottom:12px;">📱 ' + escapeHTML(contact.phone) + '</div>' +
            '<button class="btn-primary contact-profile-btn" onclick="switchToChat(\'' + contact.id + '\')">💬 ' + t('write') + '</button>' +
            '<button class="btn-secondary contact-profile-btn" onclick="buildContacts()" style="margin-top:8px;">← ' + t('back_to_contacts') + '</button>' +
        '</div>';
}

function switchToChat(contactId) {
    showView('msg');
    clearChat();
    
    var contacts = (typeof CONTACTS_DATA !== 'undefined') ? CONTACTS_DATA : [];
    var contact = null;
    
    for (var i = 0; i < contacts.length; i++) {
        if (contacts[i].id === contactId) {
            contact = contacts[i];
            break;
        }
    }
    
    if (!contact) return;
    
    var avatar = document.getElementById('msgAva');
    if (avatar) avatar.innerHTML = contact.avatar;
    
    var contactName = getContactField(contact, 'name');
    setContactName(contactName);
    setContactStatus(getContactStatusLabel(contact), contact.statusCode === 'online' ? 'online' : '');
    
    addChatDivider();
    addChatSystem(t('chat_with') + contactName);
    
    if (contactId === 'anna' && !G.gameStarted) {
        G.gameStarted = true;
        AchievementSystem.unlock('first_contact');
        setTimeout(function() {
            if (typeof startGame === 'function') {
                startGame();
            }
        }, 800);
    } else if (contactId === 'katya') {
        if (typeof KatyaSystem !== 'undefined' && typeof KatyaSystem.startChat === 'function') {
            KatyaSystem.startChat();
        } else {
            addMessage('in', 'Привет! Это Катя. Я хотела поговорить о доме №7.', { id: 'katya_fallback' });
        }
    } else if (contactId === 'mama') {
        setTimeout(function() {
            annaTyping(1500, { mood: 'calm', fear: 10 }).then(function() {
                addMessage('in', 'Сынок, ты покушал? Опять в своём телефоне сидишь?', { id: 'mama_1' });
                GameTime.advance(1);
                return sleep(1000);
            }).then(function() {
                addMessage('in', 'Приходи в воскресенье на борщ. И не забудь шапку надеть!', { id: 'mama_2' });
            });
        }, 500);
    } else {
        setTimeout(function() {
            annaTyping(1800, { mood: 'calm', fear: 20 }).then(function() {
                var greetIdx = Math.floor(Math.random() * 4);
                addMessage('in', '', { id: 'generic_greeting_' + greetIdx });
            });
        }, 500);
    }
}


