function getNoteField(note, field) {
    var key = 'note_' + note.id + '_' + field;
    if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
    return note[field];
}

var currentNote = null;

function buildNotes() {
    var list = document.getElementById('noteList');
    var detail = document.getElementById('noteDet');
    var backBtn = document.getElementById('noteBack');
    
    if (list) list.style.display = 'block';
    if (detail) {
        detail.style.display = 'none';
        detail.className = 'notes-detail';
    }
    if (backBtn) backBtn.onclick = goHome;
    
    if (!list) return;
    
    currentNote = null;
    
    var html = '';
    for (var i = 0; i < NOTES_DATA.length; i++) {
        var note = NOTES_DATA[i];
        var isLocked = note.locked && G.notesUnlocked.indexOf(note.id) === -1;
        var noteBody = getNoteField(note, 'body');
        var preview = isLocked ? '🔒 ' + (t('locked') || 'Заблокировано') : noteBody.substring(0, 50) + '...';
        
        html += '<div class="note-card" onclick="' + (isLocked ? "showToast('🔒 " + (t('password_required') || 'Требуется пароль: 2305') + "', '" + (t('notes') || 'Заметки') + "')" : "openNote('" + note.id + "')") + '">' +
            '<div class="note-card-title">' + escapeHTML(getNoteField(note, 'title')) + '</div>' +
            '<div class="note-card-preview" style="' + (isLocked ? 'color:var(--text-tertiary);font-style:italic;' : '') + '">' +
                (isLocked ? '🔒 ' + (t('enter_password') || 'Введите пароль для просмотра') : escapeHTML(preview)) +
            '</div>' +
            '<div class="note-card-date">' + escapeHTML(getNoteField(note, 'date')) + '</div>' +
            (isLocked ? '<div style="position:absolute;top:12px;right:12px;font-size:14px;">🔒</div>' : '') +
        '</div>';
    }
    
    list.innerHTML = html;
}

function openNote(noteId) {
    if (!G.notesUnlocked) G.notesUnlocked = [];
    
    var note = null;
    for (var i = 0; i < NOTES_DATA.length; i++) {
        if (NOTES_DATA[i].id === noteId) {
            note = NOTES_DATA[i];
            break;
        }
    }
    
    if (!note) return;
    
    if (note.locked && G.notesUnlocked.indexOf(note.id) === -1) {
        var password = prompt((t('enter_password_prompt') || 'Введите пароль для доступа к заметке:'));
        if (password === null) return;
        if (password === note.password) {
            G.notesUnlocked.push(note.id);
            showToast('🔓 ' + (t('note_unlocked') || 'Заметка разблокирована!'), (t('notes') || 'Заметки'));
        } else {
            showToast('❌ ' + (t('wrong_password') || 'Неверный пароль'), (t('notes') || 'Заметки'));
        }
        return;
    }
    
    renderNoteDetail(note);
}

function renderNoteDetail(note) {
    var list = document.getElementById('noteList');
    var detail = document.getElementById('noteDet');
    var backBtn = document.getElementById('noteBack');
    
    if (list) list.style.display = 'none';
    if (detail) {
        detail.style.display = 'block';
        detail.className = 'notes-detail show';
        detail.innerHTML = 
            '<div class="note-detail-title">' + escapeHTML(getNoteField(note, 'title')) + '</div>' +
            '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);margin-bottom:16px;">' + escapeHTML(getNoteField(note, 'date')) + '</div>' +
            '<div class="note-detail-body">' + escapeHTML(getNoteField(note, 'body')).replace(/\n/g, '<br>') + '</div>';
    }
    if (backBtn) {
        backBtn.onclick = function() {
            if (detail) {
                detail.style.display = 'none';
                detail.className = 'notes-detail';
            }
            if (list) {
                list.style.display = 'block';
                list.className = 'notes-list';
            }
            backBtn.onclick = goHome;
            currentNote = null;
        };
    }
    currentNote = note.id;
}

