    for (var li = 0; li < langKeys.length; li++) {
        var lang = langKeys[li];
        html += '<div class="settings-option settings-option-lang ' + (currentLang === lang ? 'selected' : '') + '" onclick="setLanguage(\'' + lang + '\');buildSettings()">' + langNames[lang] + '</div>';
    }
    html += '</div>';
    
