function getDictField(rec, field) {
    var key = 'dict_' + rec.id + '_' + field;
    if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
    return rec[field];
}

function getDictLine(rec, idx) {
    var key = 'dict_' + rec.id + '_line' + idx;
    if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
    return rec.transcription[idx].text;
}

function buildDictaphone() {
    var view = document.getElementById('dictaphone');
    if (!view) return;
    
    var list = view.querySelector('.dictaphone-list');
    var detail = view.querySelector('.dictaphone-detail');
    
    if (list) list.style.display = 'block';
    if (detail) detail.style.display = 'none';
    
    if (!list) return;
    
    for (var i = 0; i < DICTAHONE_DATA.length; i++) {
        var rec = DICTAHONE_DATA[i];
        if (rec.unlockAct && G.act >= rec.unlockAct) {
            rec.locked = false;
        }
    }
    
    var html = '';
    for (var ri = 0; ri < DICTAHONE_DATA.length; ri++) {
        var rec = DICTAHONE_DATA[ri];
        var isLocked = rec.locked && G.act < (rec.unlockAct || 999);
        
        html += '<div class="record-item ' + (isLocked ? 'locked' : '') + '" onclick="' + (isLocked ? "showToast('🔒 " + (t('recording_locked') || 'Запись заблокирована') + "', '" + (t('dictaphone') || 'Диктофон') + "')" : "openDictaphoneRecording('" + rec.id + "')") + '">' +
            '<div class="record-header">' +
                '<div class="record-icon ' + rec.type + '">' + rec.icon + '</div>' +
                '<div class="record-meta">' +
                    '<div class="record-title">' + (isLocked ? '🔒 ' + (t('locked') || 'Заблокировано') : escapeHTML(getDictField(rec, 'title'))) + '</div>' +
                    '<div class="record-date">' + escapeHTML(getDictField(rec, 'date')) + '</div>' +
                '</div>' +
                '<div class="record-duration">' + rec.duration + '</div>' +
            '</div>' +
            (!isLocked ? '<div class="record-preview">' + escapeHTML(getDictLine(rec, 0).substring(0, 70)) + '...</div>' : '') +
        '</div>';
    }
    
    list.innerHTML = html;
}

function openDictaphoneRecording(id) {
    var rec = null;
    for (var i = 0; i < DICTAHONE_DATA.length; i++) {
        if (DICTAHONE_DATA[i].id === id) {
            rec = DICTAHONE_DATA[i];
            break;
        }
    }
    
    if (!rec || rec.locked) return;
    
    var view = document.getElementById('dictaphone');
    if (!view) return;
    
    var list = view.querySelector('.dictaphone-list');
    var detail = view.querySelector('.dictaphone-detail');
    
    if (list) list.style.display = 'none';
    if (detail) {
        detail.style.display = 'block';
        detail.className = 'dictaphone-detail show';
        
        var transcriptionHtml = '';
        for (var ti = 0; ti < rec.transcription.length; ti++) {
            var line = rec.transcription[ti];
            var lineText = escapeHTML(getDictLine(rec, ti));
            if (line.speaker === 'note') {
                transcriptionHtml += '<div class="transcription-line note">' + lineText + '</div>';
            } else {
                transcriptionHtml += '<div class="transcription-line ' + line.speaker + '">' + lineText + '</div>';
            }
        }
        
        detail.innerHTML = 
            '<div class="detail-header">' +
                '<div class="detail-play-btn" onclick="simulateDictaphonePlayback(this, \'' + rec.id + '\')">▶</div>' +
                '<div class="detail-info">' +
                    '<div class="detail-title">' + escapeHTML(getDictField(rec, 'title')) + '</div>' +
                    '<div class="detail-subtitle">' + escapeHTML(getDictField(rec, 'date')) + ' · ' + rec.duration + '</div>' +
                '</div>' +
            '</div>' +
            '<div class="transcription-container">' +
                transcriptionHtml +
                (rec.note ? '<div class="transcription-note">📌 ' + escapeHTML(getDictField(rec, 'note')) + '</div>' : '') +
            '</div>' +
            '<button class="btn-secondary" onclick="buildDictaphone()" style="margin-top:16px;width:100%;">← ' + (t('back_to_recordings') || 'Назад к записям') + '</button>';
    }
}

function simulateDictaphonePlayback(btn, id) {
    if (!btn) return;
    
    if (btn.classList.contains('playing')) {
        btn.classList.remove('playing');
        btn.textContent = '▶';
        var allLines = document.querySelectorAll('#dictaphone .transcription-line');
        for (var li = 0; li < allLines.length; li++) {
            allLines[li].style.background = '';
        }
        return;
    }
    
    btn.classList.add('playing');
    btn.textContent = '⏸';
    
    var rec = null;
    for (var ri = 0; ri < DICTAHONE_DATA.length; ri++) {
        if (DICTAHONE_DATA[ri].id === id) {
            rec = DICTAHONE_DATA[ri];
            break;
        }
    }
    
    if (!rec) {
        btn.classList.remove('playing');
        btn.textContent = '▶';
        return;
    }
    
    var durMatch = rec.duration.match(/(\d+):(\d+)/);
    var totalSecs = durMatch ? parseInt(durMatch[1]) * 60 + parseInt(durMatch[2]) : 60;
    
    var detail = btn.closest('.dictaphone-detail');
    var lines = detail ? detail.querySelectorAll('.transcription-line') : [];
    
    var index = 0;
    var interval = (totalSecs * 1000) / Math.max(lines.length, 1);
    
    function highlightNext() {
        if (index > 0 && lines[index - 1]) {
            lines[index - 1].style.background = '';
        }
        if (index < lines.length) {
            lines[index].style.background = 'rgba(124, 92, 252, 0.1)';
            lines[index].style.borderRadius = '4px';
            index++;
            setTimeout(highlightNext, interval);
        } else {
            btn.classList.remove('playing');
            btn.textContent = '▶';
        }
    }
    
    highlightNext();
}

