// 37. КАЛЬКУЛЯТОР
// ═══════════════════════════════════════════════════════════════

var PhoneCalculator = {
    display: '0',
    current: null,
    operator: null,
    waitingForOperand: false,
    secretBuffer: '',
    secretAttempts: 0,
    secretUnlocked: false,

    init: function() {
        if (G.calcSecretUnlocked) this.secretUnlocked = true;
        this.updateDisplay();
    },

    updateDisplay: function() {
        var el = document.getElementById('calcResult');
        if (el) el.textContent = this.display;
    },

    inputDigit: function(d) {
        d = String(d);
        if (this.waitingForOperand) {
            this.display = d;
            this.waitingForOperand = false;
        } else {
            this.display = (this.display === '0') ? d : this.display + d;
        }
        this.secretBuffer += d;
        if (this.secretBuffer.length > 12) this.secretBuffer = this.secretBuffer.slice(-12);
        this.updateDisplay();
    },

    inputDecimal: function() {
        if (this.waitingForOperand) {
            this.display = '0.';
            this.waitingForOperand = false;
        } else if (this.display.indexOf('.') === -1) {
            this.display += '.';
        }
        this.updateDisplay();
    },

    compute: function(a, b, op) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '×': return a * b;
            case '÷': return b !== 0 ? a / b : 0;
            default: return b;
        }
    },

    handleOperator: function(op) {
        var inputValue = parseFloat(this.display);
        
        if (op === '=') {
            this.checkSecretCode();
        }
        
        if (this.current === null || this.operator === null) {
            this.current = inputValue;
        } else if (this.operator) {
            var result = this.compute(this.current, inputValue, this.operator);
            this.current = result;
            this.display = String(Math.round(result * 100000) / 100000);
        }
        
        this.waitingForOperand = true;
        this.operator = (op === '=') ? null : op;
        if (op === '=') this.current = null;
        this.updateDisplay();
    },

    checkSecretCode: function() {
        if (this.secretUnlocked) return;
        
        var cleanDisplay = this.display.replace(/[^0-9]/g, '');
        if (cleanDisplay === '2305' || this.secretBuffer.indexOf('2305') !== -1) {
            this.secretUnlocked = true;
            G.calcSecretUnlocked = true;
            
            if (!G.galleryUnlocked) G.galleryUnlocked = [];
            if (G.galleryUnlocked.indexOf('g5') === -1) {
                G.galleryUnlocked.push('g5');
            }
            
            showToast('🔓 ' + (t('calc_secret_unlocked') || 'Секретный файл разблокирован!'), t('calculator'));
            
            var hint = document.getElementById('calcHint');
            if (hint) {
                hint.textContent = '✓ ' + (t('unlocked') || 'РАЗБЛОКИРОВАН');
                hint.classList.add('visible');
                hint.style.opacity = '1';
            }
            
            this.secretBuffer = '';
        } else {
            this.secretAttempts++;
        }
    },

    reset: function() {
        this.display = '0';
        this.current = null;
        this.operator = null;
        this.waitingForOperand = false;
        this.secretBuffer = '';
        this.updateDisplay();
    }
};

function buildCalculator() {
    var view = document.getElementById('calculator');
    if (!view) return;
    
    var body = view.querySelector('.calc-body');
    if (!body) return;
    
    if (typeof PhoneCalculator === 'undefined') {
        body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-tertiary);">' + (t('loading') || 'Загрузка...') + '</div>';
        return;
    }
    
    PhoneCalculator.init();
    
    body.innerHTML = 
        '<div class="calc-display" style="background:var(--depth);border:1px solid var(--b0);border-radius:24px;padding:20px;text-align:right;margin-bottom:16px;min-height:100px;display:flex;flex-direction:column;justify-content:flex-end;">' +
            '<div class="calc-result" id="calcResult" style="font-family:var(--font-heading);font-size:48px;font-weight:700;color:var(--t0);word-break:break-all;">0</div>' +
        '</div>' +
        '<div class="calc-grid" style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:0 4px;">' +
            '<button onclick="PhoneCalculator.reset()" style="grid-column:span 2;background:rgba(255,58,112,0.2);border:1px solid rgba(255,58,112,0.3);color:var(--crimson);font-family:var(--font-heading);font-size:20px;font-weight:700;border-radius:18px;cursor:pointer;transition:all 0.15s ease;">C</button>' +
            '<button onclick="PhoneCalculator.handleOperator(\'÷\')" style="background:rgba(124,92,252,0.2);border:1px solid rgba(124,92,252,0.3);color:var(--violet);font-family:var(--font-heading);font-size:20px;font-weight:700;border-radius:18px;cursor:pointer;transition:all 0.15s ease;">÷</button>' +
            '<button onclick="PhoneCalculator.handleOperator(\'×\')" style="background:rgba(124,92,252,0.2);border:1px solid rgba(124,92,252,0.3);color:var(--violet);font-family:var(--font-heading);font-size:20px;font-weight:700;border-radius:18px;cursor:pointer;transition:all 0.15s ease;">×</button>' +
            '<button onclick="PhoneCalculator.inputDigit(7)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">7</button>' +
            '<button onclick="PhoneCalculator.inputDigit(8)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">8</button>' +
            '<button onclick="PhoneCalculator.inputDigit(9)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">9</button>' +
            '<button onclick="PhoneCalculator.handleOperator(\'-\')" style="background:rgba(124,92,252,0.2);border:1px solid rgba(124,92,252,0.3);color:var(--violet);font-family:var(--font-heading);font-size:20px;font-weight:700;border-radius:18px;cursor:pointer;transition:all 0.15s ease;">−</button>' +
            '<button onclick="PhoneCalculator.inputDigit(4)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">4</button>' +
            '<button onclick="PhoneCalculator.inputDigit(5)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">5</button>' +
            '<button onclick="PhoneCalculator.inputDigit(6)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">6</button>' +
            '<button onclick="PhoneCalculator.handleOperator(\'+\')" style="background:rgba(124,92,252,0.2);border:1px solid rgba(124,92,252,0.3);color:var(--violet);font-family:var(--font-heading);font-size:20px;font-weight:700;border-radius:18px;cursor:pointer;transition:all 0.15s ease;">+</button>' +
            '<button onclick="PhoneCalculator.inputDigit(1)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">1</button>' +
            '<button onclick="PhoneCalculator.inputDigit(2)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">2</button>' +
            '<button onclick="PhoneCalculator.inputDigit(3)" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">3</button>' +
            '<button onclick="PhoneCalculator.handleOperator(\'=\')" style="background:var(--violet);border-color:var(--violet);color:#fff;font-family:var(--font-heading);font-size:28px;font-weight:700;border-radius:18px;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">=</button>' +
            '<button onclick="PhoneCalculator.inputDigit(0)" style="grid-column:span 2;aspect-ratio:2/1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">0</button>' +
            '<button onclick="PhoneCalculator.inputDecimal()" style="aspect-ratio:1;border-radius:18px;border:1px solid var(--b0);background:var(--surface);color:var(--t1);font-family:var(--font-heading);font-size:22px;font-weight:600;cursor:pointer;transition:all 0.15s ease;display:flex;align-items:center;justify-content:center;">.</button>' +
        '</div>' +
        '<div class="calc-secret-hint' + (G.act >= 2 || (typeof PhoneCalculator !== 'undefined' && PhoneCalculator.secretAttempts >= 3) ? ' visible' : '') + '" id="calcHint" style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);text-align:center;margin-top:16px;opacity:0;transition:opacity 2s;">' +
            ((typeof PhoneCalculator !== 'undefined' && PhoneCalculator.secretUnlocked) ? '✓ ' + (t('unlocked') || 'РАЗБЛОКИРОВАН') : (t('code') || 'Код') + ': 2305') +
        '</div>';
    
    var buttons = body.querySelectorAll('.calc-grid button');
    for (var bi = 0; bi < buttons.length; bi++) {
        (function(btn) {
            btn.addEventListener('mousedown', function() {
                this.style.transform = 'scale(0.92)';
            });
            btn.addEventListener('mouseup', function() {
                this.style.transform = '';
            });
            btn.addEventListener('mouseleave', function() {
                this.style.transform = '';
            });
        })(buttons[bi]);
    }
}

// ═══════════════════════════════════════════════════════════════
// 38. ДОСКА РАССЛЕДОВАНИЯ
// ═══════════════════════════════════════════════════════════════

function buildInvestigationBoard() {
    var view = document.getElementById('investigation');
    if (!view) return;
    
    var body = view.querySelector('.investigation-body');
    if (!body) return;
    
    if (typeof ClueSystem === 'undefined') {
        body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-tertiary);">' + (t('loading') || 'Загрузка...') + '</div>';
        return;
    }
    
    var foundClues = ClueSystem.getFoundCount();
    var totalClues = ClueSystem.clues.length;
    var criticalFound = ClueSystem.getCriticalFound();
    var totalCritical = 0;
    for (var ci = 0; ci < ClueSystem.clues.length; ci++) {
        if (ClueSystem.clues[ci].critical) totalCritical++;
    }
    
    var html = '';
    html += '<div style="font-family:var(--font-heading);font-size:12px;font-weight:700;color:var(--t0);margin-bottom:8px;">🕵️ ' + (t('investigation_board') || 'ДОСКА РАССЛЕДОВАНИЯ') + '</div>';
    html += '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);margin-bottom:16px;">' + (t('clues_found') || 'Найдено улик') + ': ' + foundClues + '/' + totalClues + ' · ' + (t('critical') || 'Критических') + ': ' + criticalFound + '/' + totalCritical + '</div>';
    html += '<div style="height:4px;background:var(--depth);border-radius:2px;margin-bottom:16px;overflow:hidden;">' +
        '<div style="height:100%;width:' + ((foundClues/totalClues)*100) + '%;background:linear-gradient(90deg,var(--violet),var(--teal));border-radius:2px;transition:width 0.5s ease;"></div>' +
    '</div>';
    
    for (var cli = 0; cli < ClueSystem.clues.length; cli++) {
        var clue = ClueSystem.clues[cli];
        var clueTitle = ClueSystem.getTitle(clue.id);
        var clueDesc = ClueSystem.getDesc(clue.id);
        var escapedDesc = escapeHTML(clueDesc);
        
        html += '<div class="clue-card' + (clue.found ? ' found' : '') + (clue.critical ? ' critical' : '') + '" onclick="' + (clue.found ? "showToast('" + escapedDesc + "', '" + escapeHTML(clueTitle) + "')" : "showToast('🔒 " + (t('clue_not_found') || 'Улика ещё не найдена') + "', '" + (t('investigation') || 'Расследование') + "')") + '">' +
            '<div class="clue-header">' +
                '<div class="clue-icon" style="background:' + (clue.found ? 'rgba(0,229,176,0.15)' : 'rgba(255,255,255,0.03)') + '">' + clue.icon + '</div>' +
                '<div class="clue-title">' + (clue.found ? escapeHTML(clueTitle) : '???') + '</div>' +
                (clue.critical ? '<span style="font-family:var(--font-mono);font-size:7px;color:var(--crimson);background:rgba(255,58,112,0.1);padding:2px 6px;border-radius:4px;border:1px solid rgba(255,58,112,0.2);">' + (t('critical') || 'КРИТИЧЕСКАЯ') + '</span>' : '') +
            '</div>' +
            (clue.found ? '<div class="clue-desc">' + escapeHTML(clueDesc) + '</div>' : '<div class="clue-desc" style="color:var(--text-tertiary);font-style:italic;">' + (t('not_detected') || 'Не обнаружено') + '</div>') +
            '<div class="clue-status' + (clue.found ? ' found' : '') + '">' + (clue.found ? '✓ ' + (t('found') || 'Найдено') : '○ ' + (t('not_found') || 'Не найдено')) + '</div>' +
        '</div>';
    }
    
    if (foundClues >= 4) {
        html += '<div class="board-connections"><strong>📊 ' + (t('connections') || 'СВЯЗИ') + ':</strong><br>';
        for (var ci2 = 0; ci2 < ClueSystem.clues.length; ci2++) {
            var c = ClueSystem.clues[ci2];
            if (!c.found) continue;
            var connections = ClueSystem.getConnections(c.id);
            var foundConnections = [];
            for (var ci3 = 0; ci3 < connections.length; ci3++) {
                if (connections[ci3] && connections[ci3].found) {
                    foundConnections.push(escapeHTML(ClueSystem.getTitle(connections[ci3].id)));
                }
            }
            if (foundConnections.length > 0) {
                html += '• ' + escapeHTML(ClueSystem.getTitle(c.id)) + ' → ' + foundConnections.join(', ') + '<br>';
            }
        }
        html += (t('continue_investigation') || 'Продолжайте расследование, чтобы раскрыть полную картину.') + '</div>';
    }
    
    body.innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════
// 39. ДНЕВНИК АННЫ
// ═══════════════════════════════════════════════════════════════

function getDiaryField(entry, field) {
    var key = 'diary_' + entry.id + '_' + field;
    if (I18N[currentLang] && I18N[currentLang][key]) return t(key);
    return entry[field];
}

function buildDiary() {
    var view = document.getElementById('diary');
    if (!view) return;
    
    var body = view.querySelector('.diary-body');
    if (!body) return;
    
    if (typeof DiaryData === 'undefined') {
        body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-tertiary);">' + (t('loading') || 'Загрузка...') + '</div>';
        return;
    }
    
    if (G.diaryRead === undefined) G.diaryRead = false;
    
    if (!G.diaryRead && G.act >= 2) {
        G.diaryRead = true;
        ReputationSystem.addXP('diary_read');
        AchievementSystem.check('diary_fan');
    }
    
    var html = '';
    for (var di = 0; di < DiaryData.length; di++) {
        var entry = DiaryData[di];
        var isLocked = entry.locked && (!entry.unlockAct || G.act < entry.unlockAct);
        var isUnlocked = !isLocked && (G.diaryUnlocked.indexOf(entry.id) !== -1 || !entry.locked);
        
        var clickAction = isLocked ? "showToast('🔒 " + (t('diary_locked') || 'Запись заблокирована') + "', '" + (t('diary') || 'Дневник') + "')" : (isUnlocked ? "showDiaryEntry('" + entry.id + "')" : "showToast('🔒 " + (t('not_unlocked_yet') || 'Запись ещё не открыта') + "', '" + (t('diary') || 'Дневник') + "')");
        
        html += '<div class="diary-entry' + (isLocked ? ' locked' : '') + '" onclick="' + clickAction + '">' +
            '<div class="diary-mood">' + (isLocked ? '🔒' : entry.mood) + '</div>' +
            '<div class="diary-date">' + escapeHTML(getDiaryField(entry, 'date')) + '</div>' +
            '<div class="diary-title">' + (isLocked ? (t('locked') || 'ЗАБЛОКИРОВАНО') : escapeHTML(getDiaryField(entry, 'title'))) + '</div>' +
            '<div class="diary-text">' + (isLocked ? (t('diary_locked_msg') || 'Эта запись станет доступна позже по сюжету.') : escapeHTML(getDiaryField(entry, 'text'))) + '</div>' +
        '</div>';
    }
    
    body.innerHTML = html;
}

function showDiaryEntry(id) {
    if (typeof DiaryData === 'undefined') return;
    
    var entry = null;
    for (var i = 0; i < DiaryData.length; i++) {
        if (DiaryData[i].id === id) {
            entry = DiaryData[i];
            break;
        }
    }
    if (!entry || entry.locked) return;
    
    showToast(getDiaryField(entry, 'text'), '📔 ' + getDiaryField(entry, 'title'));
}

// ═══════════════════════════════════════════════════════════════
// 40. КОЛЛЕКЦИЯ КОНЦОВОК
// ═══════════════════════════════════════════════════════════════

function showEndingsCollection() {
    var body = document.getElementById('endingsBody');
    if (!body) return;
    
    var unlocked = (typeof EndingsSystem !== 'undefined') ? EndingsSystem.getUnlockedCount() : 0;
    var total = (typeof EndingsSystem !== 'undefined') ? EndingsSystem.getTotalCount() : 8;
    
    var html = '';
    html += '<div class="endings-progress">🏆 ' + (t('endings_unlocked') || 'Открыто концовок') + ': ' + unlocked + '/' + total;
    html += '<div style="height:4px;background:var(--depth);border-radius:2px;margin-top:8px;overflow:hidden;">' +
        '<div style="height:100%;width:' + ((unlocked/total)*100) + '%;background:linear-gradient(90deg,var(--gold),var(--teal));border-radius:2px;transition:width 0.5s ease;"></div>' +
    '</div></div>';
    
    if (typeof EndingsSystem !== 'undefined') {
        var endings = EndingsSystem.getAllEndings();
        var endKeys = Object.keys(endings);
        for (var ei = 0; ei < endKeys.length; ei++) {
            var ending = endings[endKeys[ei]];
            html += '<div class="diary-entry" style="' + (ending.unlocked ? '' : 'opacity:0.4;') + '">' +
                '<div class="diary-mood">' + (ending.unlocked ? ending.icon : '🔒') + '</div>' +
                '<div class="diary-title">' + (ending.unlocked ? escapeHTML(EndingsSystem.getName(ending.id)) : '???') + '</div>' +
                '<div class="diary-text">' + (ending.unlocked ? escapeHTML(EndingsSystem.getDesc(ending.id)) : (t('ending_locked') || 'Эта концовка ещё не открыта.')) + '</div>' +
                (ending.unlocked ? '<span class="ending-badge unlocked">✅ ' + (t('unlocked') || 'ОТКРЫТО') + '</span>' : '<span class="ending-badge locked">🔒 ' + (t('locked') || 'ЗАКРЫТО') + '</span>') +
                (ending.unlocked ? '<div style="font-family:var(--font-mono);font-size:8px;color:var(--text-tertiary);margin-top:4px;">ID: ' + endKeys[ei] + '</div>' : '') +
            '</div>';
        }
    } else {
        html += '<div style="padding:20px;text-align:center;color:var(--text-tertiary);">' + (t('loading') || 'Загрузка...') + '</div>';
    }
    
    body.innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════
// 41. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ═══════════════════════════════════════════════════════════════

function escapeHTML(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

// ═══════════════════════════════════════════════════════════════
// 42. ПОЛНОЦЕННЫЙ МАГАЗИН ПРИЛОЖЕНИЙ
// ═══════════════════════════════════════════════════════════════

function buildAppStore() {
    var body = document.getElementById('appstoreBody');
    if (!body) return;
    
    if (typeof AppStore === 'undefined') {
        body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-tertiary);">' + (t('loading') || 'Загрузка...') + '</div>';
        return;
    }
    
    var lockedApps = AppStore.getLockedApps();
    var installedCount = AppStore.getAvailableApps().length;
    var totalApps = Object.keys(AppStore.apps).length;
    var pct = totalApps > 0 ? Math.round((installedCount / totalApps) * 100) : 0;
    
    var html = '';
    html += '<div class="appstore-header">🏪 ' + t('app_store') + '</div>';
    html += '<div class="appstore-subtitle">' + installedCount + ' / ' + totalApps + ' ' + (t('apps_installed') || 'приложений установлено') + '</div>';
    html += '<div class="appstore-progress-track"><div class="appstore-progress-fill" style="width:' + pct + '%;"></div></div>';
    
    // Поиск
    html += '<div style="margin:14px 0;padding:0 4px;">' +
        '<input type="text" id="appstoreSearch" placeholder="🔍 ' + (t('search_apps') || 'Поиск приложений...') + '" style="width:100%;padding:10px 14px;border-radius:14px;border:1px solid var(--border-color);background:var(--bg-input);color:var(--text-primary);font-family:var(--font-mono);font-size:11px;outline:none;transition:border-color 0.3s;">' +
    '</div>';
    
    // Разбиваем список заблокированных на "готовы к установке" и "ещё впереди"
    var ready = [];
    var comingLater = [];
    for (var i = 0; i < lockedApps.length; i++) {
        var la = lockedApps[i];
        if (la.id === 'support' || la.id === 'authors' || la.id === 'settings') continue;
        if (la.readyToInstall) ready.push(la); else comingLater.push(la);
    }
    
    // ─── Витрина: приложение готово к установке ───
    if (ready.length > 0) {
        var feat = ready[0];
        var featBg = feat.gradient || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)';
        html += '<div class="appstore-featured" style="background:' + featBg + ';" onclick="openAppDetail(\'' + feat.id + '\')">' +
            '<div class="appstore-featured-badge">' + (t('new_badge') || 'НОВОЕ') + '</div>' +
            '<div class="appstore-featured-icon">' + feat.icon + '</div>' +
            '<div class="appstore-featured-info">' +
                '<div class="appstore-featured-eyebrow">' + (t('ready_to_install') || 'Готово к установке') + '</div>' +
                '<div class="appstore-featured-name">' + AppStore.getField(feat.id, 'name') + '</div>' +
                '<div class="appstore-featured-cat">' + (AppStore.getField(feat.id, 'category') || 'Приложение') + '</div>' +
            '</div>' +
            '<div class="appstore-featured-cta">' + (t('install') || 'Установить') + ' ›</div>' +
        '</div>';
    }
    
    // ─── Готовы к установке (список) ───
    if (ready.length > 0) {
        html += '<div class="appstore-section-title" style="color:var(--violet);">📦 ' + (t('available_for_install') || 'ДОСТУПНЫ ДЛЯ УСТАНОВКИ') + ' (' + ready.length + ')</div>';
        for (var j = 0; j < ready.length; j++) {
            var app = ready[j];
            var iconBg = app.gradient || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)';
            html += '<div class="appstore-item" data-app-id="' + app.id + '" onclick="openAppDetail(\'' + app.id + '\')">' +
                '<div class="appstore-item-icon" style="background:' + iconBg + ';">' + app.icon + '</div>' +
                '<div class="appstore-item-info">' +
                    '<div class="appstore-item-name">' + AppStore.getField(app.id, 'name') + '</div>' +
                    '<div class="appstore-item-desc">' + (AppStore.getField(app.id, 'category') || 'Приложение') + '</div>' +
                '</div>' +
                '<button class="appstore-item-btn get" data-app-id="' + app.id + '" onclick="event.stopPropagation();quickInstallApp(\'' + app.id + '\', this)">' +
                    '<span class="btn-fill"></span><span class="btn-label">' + (t('install') || 'УСТАНОВИТЬ') + '</span>' +
                '</button>' +
            '</div>';
        }
    }
    
    // ─── Ещё впереди (по сюжету) ───
    if (comingLater.length > 0) {
        html += '<div class="appstore-section-title" style="color:var(--text-tertiary);">🔒 ' + (t('coming_soon') || 'ЕЩЁ ВПЕРЕДИ') + ' (' + comingLater.length + ')</div>';
        for (var c = 0; c < comingLater.length; c++) {
            var lapp = comingLater[c];
            var iconBg3 = lapp.gradient || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)';
            html += '<div class="appstore-item locked" data-app-id="' + lapp.id + '" onclick="openAppDetail(\'' + lapp.id + '\')">' +
                '<div class="appstore-item-icon" style="background:' + iconBg3 + ';filter:grayscale(0.6);">' + lapp.icon + '</div>' +
                '<div class="appstore-item-info">' +
                    '<div class="appstore-item-name">' + AppStore.getField(lapp.id, 'name') + '</div>' +
                    '<div class="appstore-item-desc">' + (AppStore.getField(lapp.id, 'category') || 'Приложение') + ' · ' + (t('locked_hint') || 'по ходу сюжета') + '</div>' +
                '</div>' +
                '<div class="appstore-item-lock">🔒</div>' +
            '</div>';
        }
    }
    
    if (ready.length === 0 && comingLater.length === 0) {
        html += '<div style="text-align:center;padding:20px;color:var(--text-tertiary);font-family:var(--font-mono);font-size:11px;">' + (t('no_apps_available') || 'Нет приложений для установки') + '</div>';
    }
    
    // ─── Уже установленные ───
    var installed = AppStore.getAvailableApps();
    var installedApps = [];
    for (var k = 0; k < installed.length; k++) {
        var appId = installed[k];
        if (AppStore.apps[appId]) {
            installedApps.push(AppStore.apps[appId]);
        }
    }
    
    if (installedApps.length > 0) {
        html += '<div class="appstore-section-title" style="color:var(--teal);">✅ ' + (t('already_installed') || 'УСТАНОВЛЕНЫ') + ' (' + installedApps.length + ')</div>';
        
        for (var l = 0; l < installedApps.length; l++) {
            var iapp = installedApps[l];
            var iconBg2 = iapp.gradient || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)';
            html += '<div class="appstore-item installed" onclick="openAppDetail(\'' + iapp.id + '\')">' +
                '<div class="appstore-item-icon" style="background:' + iconBg2 + ';">' + iapp.icon + '</div>' +
                '<div class="appstore-item-info">' +
                    '<div class="appstore-item-name">' + AppStore.getField(iapp.id, 'name') + '</div>' +
                    '<div class="appstore-item-desc">' + (AppStore.getField(iapp.id, 'category') || 'Приложение') + ' · ' + (t('installed') || 'Установлено') + '</div>' +
                '</div>' +
                '<div style="color:var(--teal);font-size:20px;">✅</div>' +
            '</div>';
        }
    }
    
    // Информация о разблокировке
    html += '<div style="margin-top:20px;padding:16px;background:var(--depth);border-radius:16px;border:1px solid var(--border-color);">' +
        '<div style="font-family:var(--font-mono);font-size:9px;color:var(--text-tertiary);text-align:center;line-height:1.8;">' +
            '💡 ' + (t('appstore_hint') || 'Некоторые приложения разблокируются по ходу сюжета.<br>Продолжайте играть, чтобы открыть новые возможности!') +
        '</div>' +
    '</div>';
    
    body.innerHTML = html;
    
    // Добавляем поиск
    var searchInput = document.getElementById('appstoreSearch');
    if (searchInput) {
        searchInput.addEventListener('input', function() {
            var query = this.value.toLowerCase();
            var items = body.querySelectorAll('.appstore-item');
            for (var m = 0; m < items.length; m++) {
                var nameEl = items[m].querySelector('.appstore-item-name');
                if (nameEl) {
                    var match = nameEl.textContent.toLowerCase().indexOf(query) !== -1;
                    items[m].style.display = match ? 'flex' : 'none';
                }
            }
        });
    }
}

// ═══════════════════════════════════════════════════════════════
// 43. УСТАНОВКА ПРИЛОЖЕНИЙ (С АНИМАЦИЕЙ, БЕЗ БАГОВ ГОНКИ)
// ═══════════════════════════════════════════════════════════════

// Единая логика "скачивания" — использует и список, и страница приложения.
// app.installing защищает от повторного запуска установки одного и того же
// приложения из двух мест одновременно (баг двойной установки).
function runAppInstall(appId, onTick, onDone) {
    if (typeof AppStore === 'undefined') return false;
    var app = AppStore.apps[appId];
    if (!app || app.unlocked) return false;
    if (app.installing) return false; // уже устанавливается — не запускаем второй раз
    if (!(app.unlockCondition === 'always' || app.readyToInstall)) {
        showToast('🔒 ' + (t('app_cannot_install') || 'Это приложение нельзя установить сейчас'), t('app_store'));
        return false;
    }
    
    app.installing = true;
    var progress = 0;
    var interval = setInterval(function() {
        progress += Math.random() * 7 + 4;
        if (progress > 100) progress = 100;
        if (onTick) onTick(progress);
        
        if (progress >= 100) {
            clearInterval(interval);
            setTimeout(function() {
                app.installing = false;
                app.unlocked = true;
                app.readyToInstall = false;
                if (G.appsInstalled.indexOf(appId) === -1) {
                    G.appsInstalled.push(appId);
                }
                AppStore.save();
                
                if (typeof buildHomeGrid === 'function') buildHomeGrid();
                if (typeof buildAppStore === 'function') buildAppStore();
                
                showToast('✅ ' + AppStore.getField(appId, 'name') + ' ' + (t('installed') || 'установлено!'), t('app_store'));
                if (onDone) onDone();
            }, 350);
        }
    }, 100);
    return true;
}

// Быстрая установка прямо из списка (без открытия карточки приложения)
function quickInstallApp(appId, btnEl) {
    if (!btnEl) return;
    var app = AppStore.apps[appId];
    if (!app || app.installing) return;
    
    var fill = btnEl.querySelector('.btn-fill');
    var label = btnEl.querySelector('.btn-label');
    btnEl.classList.add('progress');
    btnEl.disabled = true;
    
    var started = runAppInstall(appId, function(progress) {
        if (fill) fill.style.width = progress + '%';
        if (label) label.textContent = Math.floor(progress) + '%';
    }, function() {
        // buildAppStore() уже перерисует список с этим приложением в разделе "Установлены"
    });
    
    if (!started) {
        btnEl.classList.remove('progress');
        btnEl.disabled = false;
    }
}

function openFromStore(appId) {
    if (typeof AppStore !== 'undefined' && AppStore.isUnlocked(appId)) {
        openApp(appId);
    } else {
        showToast('🔒 ' + (t('app_locked') || 'Приложение заблокировано'), t('system'));
    }
}

// ═══════════════════════════════════════════════════════════════
// 42.1 СТРАНИЦА ПРИЛОЖЕНИЯ (App Store — детальный вид)
// ═══════════════════════════════════════════════════════════════

function buildAppStars(rating) {
    rating = rating || 4.5;
    var full = Math.round(rating);
    var stars = '';
    for (var i = 0; i < 5; i++) {
        stars += i < full ? '★' : '☆';
    }
    return stars;
}

function buildAppScreenshots(app) {
    // Генерируем несколько абстрактных "скриншотов" интерфейса приложения,
    // стилизованных под его цветовую гамму — реальных скринов у нас нет,
    // но так карточка выглядит как настоящая страница из App Store.
    var variants = [
        [ {t:'line', top:44, w:'70%'}, {t:'line', top:60, w:'45%'}, {t:'block', top:84, h:100}, {t:'line', top:196, w:'55%'} ],
        [ {t:'block', top:40, h:70}, {t:'line', top:122, w:'60%'}, {t:'line', top:138, w:'40%'}, {t:'block', top:158, h:56} ],
        [ {t:'line', top:40, w:'50%'}, {t:'block', top:60, h:60}, {t:'block', top:128, h:60}, {t:'line', top:196, w:'65%'} ]
    ];
    var html = '';
    for (var i = 0; i < variants.length; i++) {
        var inner = '<div class="appdetail-screen-icon">' + app.icon + '</div>';
        var layout = variants[i];
        for (var j = 0; j < layout.length; j++) {
            var el = layout[j];
            if (el.t === 'line') {
                inner += '<div class="appdetail-screen-line" style="top:' + el.top + 'px;width:' + el.w + ';"></div>';
            } else {
                inner += '<div class="appdetail-screen-block" style="top:' + el.top + 'px;height:' + el.h + 'px;"></div>';
            }
        }
        html += '<div class="appdetail-screen" style="background:' + (app.gradient || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)') + ';">' + inner + '</div>';
    }
    return html;
}

function openAppDetail(appId) {
    if (typeof AppStore === 'undefined') return;
    var app = AppStore.apps[appId];
    if (!app) return;

    var screen = document.getElementById('screen');
    if (!screen) return;

    // Убираем предыдущую страницу, если открыта
    var existing = document.querySelector('.appdetail-overlay');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.className = 'appdetail-overlay';
    overlay.id = 'appdetailOverlay';

    var canInstall = app.unlockCondition === 'always' || !!app.readyToInstall;
    var actionHtml;
    if (app.unlocked) {
        actionHtml = '<button class="appdetail-btn open" onclick="closeAppDetail();openApp(\'' + appId + '\')">▶ ' + (t('open') || 'Открыть') + '</button>';
    } else if (app.installing) {
        actionHtml = '<button class="appdetail-btn downloading" disabled>⬇ ' + (t('installing') || 'Установка...') + '</button>';
    } else if (canInstall) {
        actionHtml = '<button class="appdetail-btn" id="appdetailActionBtn" onclick="installAppFromDetail(\'' + appId + '\')">⬇ ' + (t('install') || 'Установить') + '</button>';
    } else {
        actionHtml = '<button class="appdetail-btn locked" disabled>🔒 ' + (t('app_cannot_install') || 'Пока недоступно') + '</button>';
    }

    overlay.innerHTML =
        '<div class="appdetail-topbar"><div class="appdetail-back" onclick="closeAppDetail()">‹</div><div></div></div>' +
        '<div class="appdetail-hero" style="background:' + (app.gradient || 'linear-gradient(140deg,#1a1a2e,#2a2a4e)') + ';">' +
            '<div class="appdetail-icon">' + app.icon + '</div>' +
            '<div class="appdetail-name">' + AppStore.getField(appId, 'name') + '</div>' +
            '<div class="appdetail-dev">' + (app.developer || 'System') + '</div>' +
            '<div class="appdetail-category-chip">' + (AppStore.getField(appId, 'category') || 'Приложение') + '</div>' +
            '<div class="appdetail-statsrow">' +
                '<div class="appdetail-stat"><div class="appdetail-stat-value">' + (app.rating || 4.5).toFixed(1) + '</div><div class="appdetail-stat-stars">' + buildAppStars(app.rating) + '</div><div class="appdetail-stat-label">' + (t('rating') || 'Рейтинг') + '</div></div>' +
                '<div class="appdetail-stat"><div class="appdetail-stat-value">' + (AppStore.getField(appId, 'size') || '—') + '</div><div class="appdetail-stat-label">' + (t('size') || 'Размер') + '</div></div>' +
                '<div class="appdetail-stat"><div class="appdetail-stat-value">' + (app.unlocked ? (t('installed') || 'Установлено') : (t('not_installed') || 'Не установлено')) + '</div><div class="appdetail-stat-label">' + (t('status') || 'Статус') + '</div></div>' +
            '</div>' +
        '</div>' +
        '<div class="appdetail-action" id="appdetailAction">' + actionHtml + '</div>' +
        '<div class="appdetail-progress-wrap" id="appdetailProgressWrap" style="display:none;">' +
            '<div class="appdetail-progress-bar"><div class="appdetail-progress-fill" id="appdetailProgressFill"></div></div>' +
            '<div class="appdetail-progress-label" id="appdetailProgressLabel">0%</div>' +
        '</div>' +
        '<div class="appdetail-section">' +
            '<div class="appdetail-section-title">' + (t('screenshots') || 'Скриншоты') + '</div>' +
            '<div class="appdetail-screens">' + buildAppScreenshots(app) + '</div>' +
        '</div>' +
        '<div class="appdetail-section" style="padding-bottom:30px;">' +
            '<div class="appdetail-section-title">' + (t('description') || 'Описание') + '</div>' +
            '<div class="appdetail-desc">' + (AppStore.getField(appId, 'desc') || t('no_description') || 'Описание отсутствует.') + '</div>' +
        '</div>';

    screen.appendChild(overlay);
}

function closeAppDetail() {
    var overlay = document.getElementById('appdetailOverlay');
    if (overlay) overlay.remove();
}

function installAppFromDetail(appId) {
    if (typeof AppStore === 'undefined') return;
    var app = AppStore.apps[appId];
    if (!app || app.unlocked || app.installing) return;

    var actionWrap = document.getElementById('appdetailAction');
    var progressWrap = document.getElementById('appdetailProgressWrap');
    var fill = document.getElementById('appdetailProgressFill');
    var label = document.getElementById('appdetailProgressLabel');
    if (!actionWrap || !progressWrap || !fill || !label) return;

    actionWrap.innerHTML = '<button class="appdetail-btn downloading" disabled>⬇ ' + (t('installing') || 'Установка...') + '</button>';
    progressWrap.style.display = 'block';

    runAppInstall(appId, function(progress) {
        fill.style.width = progress + '%';
        label.textContent = Math.floor(progress) + '%';
    }, function() {
        label.textContent = '✅ ' + (t('installed_success') || 'Установлено!');
        actionWrap.innerHTML = '<button class="appdetail-btn open" onclick="closeAppDetail();openApp(\'' + appId + '\')">▶ ' + (t('open') || 'Открыть') + '</button>';

        var statusEls = document.querySelectorAll('#appdetailOverlay .appdetail-stat-value');
        if (statusEls && statusEls[2]) statusEls[2].textContent = (t('installed') || 'Установлено');
    });
}

