// ═══════════════════════════════════════════════════════════════
// 56. ДОПОЛНИТЕЛЬНЫЕ СИСТЕМНЫЕ ФУНКЦИИ
// ═══════════════════════════════════════════════════════════════

// Функция применения темы
function setTheme(theme) {
    if (!theme || !THEMES[theme]) theme = 'midnight';
    document.body.setAttribute('data-theme', theme);
    localStorage.setItem('nez_theme', theme);
    
    // Обновляем превью темы в настройках
    var themeOptions = document.querySelectorAll('.settings-option-theme');
    for (var i = 0; i < themeOptions.length; i++) {
        var option = themeOptions[i];
        var t = option.getAttribute('data-theme');
        option.classList.toggle('selected', t === theme);
    }
}

// Функция применения шрифта
function setFont(font) {
    if (!font || !FONTS[font]) font = 'unbounded';
    document.body.setAttribute('data-font', font);
    localStorage.setItem('nez_font', font);
    
    var fontOptions = document.querySelectorAll('.settings-option-font');
    for (var i = 0; i < fontOptions.length; i++) {
        var option = fontOptions[i];
        var f = option.getAttribute('data-font');
        option.classList.toggle('selected', f === font);
    }
}

// Переключение полноэкранного режима
function toggleFullscreen() {
    document.body.classList.toggle('fullscreen-mode');
    var isFull = document.body.classList.contains('fullscreen-mode');
    localStorage.setItem('nez_fullscreen', isFull ? 'true' : 'false');
    showToast(isFull ? (t('fullscreen_on') || 'Полноэкранный режим включён') : (t('fullscreen_off') || 'Полноэкранный режим выключен'), t('system'));
}

// Инициализация новых систем (для совместимости)
function initNewSystems() {
    // Проверяем наличие систем и инициализируем их
    if (typeof AppStore !== 'undefined') {
        AppStore.load();
    }
    
    if (typeof ContentUnlockSystem !== 'undefined') {
        ContentUnlockSystem.load();
    }
    
    if (typeof AchievementSystem !== 'undefined') {
        AchievementSystem.load();
    }
    
    if (typeof ReputationSystem !== 'undefined') {
        ReputationSystem.load();
    }
    
    if (typeof EndingsSystem !== 'undefined') {
        EndingsSystem.load();
    }
    
    if (typeof ClueSystem !== 'undefined') {
        ClueSystem.load();
    }
    
    console.log('✅ Новые системы инициализированы');
}

